const STORAGE_PREFIX='apostila-ei-cianorte-rank1-v1';
    const QUESTION_SETS={"adapted":[{"id":"A01","kind":"Questão adaptada","difficulty":"Fácil","topic":"Eixos estruturantes","stem":"Segundo a organização curricular da Educação Infantil, assinale a alternativa que apresenta os dois eixos estruturantes das práticas pedagógicas.","options":["Alfabetização e numeramento.","Interações e brincadeira.","Cuidado e disciplina.","Oralidade e escrita."],"answer":1,"explanation":"Interações e brincadeira são os eixos estruturantes. Cuidar e educar são indissociáveis, mas não formam a dupla denominada como eixos pela BNCC e pelas DCNEI.","trap":"Trocar eixos por direitos, campos ou dimensões do trabalho.","review":"Eixos estruturantes"},{"id":"A02","kind":"Questão adaptada","difficulty":"Fácil","topic":"Brincadeira","stem":"Assinale a alternativa incorreta sobre a brincadeira na Educação Infantil.","options":["Permite observar afetos, conflitos, hipóteses e modos de participação.","Pode ocorrer em diferentes tempos, espaços e parcerias.","Dispensa planejamento e observação docente porque é espontânea.","Contribui para a produção de culturas infantis e para a ampliação de experiências."],"answer":2,"explanation":"A espontaneidade da criança não elimina a intencionalidade educativa. O educador planeja condições, observa, registra e intervém sem controlar integralmente a brincadeira.","trap":"A palavra “dispensa” transforma uma ideia parcialmente verdadeira em falsa.","review":"Intencionalidade educativa"},{"id":"A03","kind":"Questão adaptada","difficulty":"Médio","topic":"Direitos de aprendizagem","stem":"Uma turma escolhe materiais, sugere caminhos para uma investigação e ajuda a organizar o espaço. O direito de aprendizagem mais diretamente evidenciado é:","options":["Participar.","Conhecer-se.","Conviver.","Expressar."],"answer":0,"explanation":"Participar envolve tomar parte das escolhas e da organização das experiências. Outros direitos podem estar presentes, mas o núcleo do caso é a participação nas decisões.","trap":"Vários direitos aparecem simultaneamente; identifique o mais diretamente descrito.","review":"Seis direitos"},{"id":"A04","kind":"Questão adaptada","difficulty":"Médio","topic":"Campos de experiências","stem":"Contação e reconto de histórias, produção de narrativas, contato com livros e hipóteses sobre a escrita relacionam-se principalmente ao campo:","options":["O eu, o outro e o nós.","Traços, sons, cores e formas.","Escuta, fala, pensamento e imaginação.","Espaços, tempos, quantidades, relações e transformações."],"answer":2,"explanation":"Oralidade, literatura, narrativas, escuta, comunicação, imaginação e cultura escrita são pistas do campo Escuta, fala, pensamento e imaginação.","trap":"Livros podem ter imagens e arte, mas o foco do enunciado é linguagem, narrativa e escrita.","review":"Palavras-chave dos campos"},{"id":"A05","kind":"Questão adaptada","difficulty":"Médio","topic":"Avaliação","stem":"Sobre avaliação na Educação Infantil, analise: I. deve acompanhar processos; II. pode usar múltiplos registros; III. deve classificar crianças prontas e não prontas; IV. não pode provocar retenção. Assinale a alternativa correta.","options":["Apenas I e II.","Apenas I, II e IV.","Apenas II e III.","I, II, III e IV."],"answer":1,"explanation":"A avaliação acompanha o desenvolvimento por observação e registros, sem seleção, promoção, classificação ou retenção.","trap":"A afirmativa III usa linguagem incompatível com a avaliação da etapa.","review":"Avaliação e registros"},{"id":"A06","kind":"Questão adaptada","difficulty":"Médio","topic":"Cuidar e educar","stem":"No momento da alimentação, a conduta mais coerente com a indissociabilidade entre cuidar e educar é:","options":["Executar o procedimento rapidamente, evitando conversas.","Separar o cuidado, realizado por auxiliares, do trabalho pedagógico do professor.","Favorecer autonomia, diálogo, hábitos de cuidado e percepção de sabores e necessidades do corpo.","Usar a alimentação apenas como intervalo entre atividades pedagógicas."],"answer":2,"explanation":"Alimentação, higiene, descanso e acolhimento também são experiências educativas e relacionais.","trap":"Tratar cuidado como assistência sem dimensão pedagógica.","review":"Cuidar e educar"},{"id":"A07","kind":"Questão adaptada","difficulty":"Médio","topic":"Grupos etários","stem":"Na BNCC, a sigla EI02 identifica objetivos destinados principalmente a:","options":["bebês, do nascimento a 1 ano e 6 meses.","crianças bem pequenas, de 1 ano e 7 meses a 3 anos e 11 meses.","crianças pequenas, de 4 anos a 5 anos e 11 meses.","estudantes do segundo ano do Ensino Fundamental."],"answer":1,"explanation":"EI indica Educação Infantil; 02 indica crianças bem pequenas.","trap":"Interpretar 02 como ano escolar.","review":"Códigos da BNCC"},{"id":"A08","kind":"Questão adaptada","difficulty":"Médio","topic":"Transição","stem":"Na transição da pré-escola para o Ensino Fundamental, a proposta pedagógica deve:","options":["antecipar sistematicamente conteúdos do primeiro ano.","selecionar as crianças consideradas prontas.","garantir continuidade, acolhimento e troca de informações, respeitando as especificidades etárias.","substituir brincadeiras por exercícios de alfabetização formal."],"answer":2,"explanation":"A transição deve evitar rupturas, apoiar-se em registros e acolhimento e não antecipar conteúdos como preparação mecânica.","trap":"Confundir continuidade com antecipação.","review":"Transição para o Ensino Fundamental"},{"id":"A09","kind":"Questão adaptada","difficulty":"Médio","topic":"Princípios das DCNEI","stem":"Autonomia, responsabilidade, solidariedade e respeito ao bem comum, ao meio ambiente e às singularidades pertencem aos princípios:","options":["éticos.","políticos.","estéticos.","administrativos."],"answer":0,"explanation":"Esse é o núcleo dos princípios éticos. Políticos remetem a cidadania, criticidade e ordem democrática; estéticos, a sensibilidade, criatividade, ludicidade e expressão.","trap":"Misturar listas verdadeiras entre os três princípios.","review":"Princípios das DCNEI"},{"id":"A10","kind":"Questão adaptada","difficulty":"Difícil","topic":"Campos e disciplinas","stem":"Assinale a afirmativa correta sobre os campos de experiências.","options":["Funcionam como disciplinas isoladas e possuem horários próprios obrigatórios.","Organizam experiências concretas e saberes das crianças em articulação com o patrimônio cultural.","Substituem a necessidade de planejamento e documentação pedagógica.","Devem ser trabalhados um por vez, evitando sobreposição."],"answer":1,"explanation":"Os campos constituem um arranjo curricular integrado. Uma experiência pode mobilizar vários campos ao mesmo tempo.","trap":"Escolarizar a Educação Infantil por meio de disciplinas fragmentadas.","review":"Campos de experiências"}],"authorial":[{"id":"B01","kind":"Questão autoral","difficulty":"Fácil","topic":"Concepção de criança","stem":"A concepção de criança adotada pelas DCNEI e retomada pela BNCC entende a criança como:","options":["receptora passiva de conteúdos definidos pelo adulto.","sujeito histórico e de direitos, que produz cultura e constrói sentidos.","adulto incompleto cuja principal tarefa é preparar-se para a escolarização.","indivíduo naturalmente autônomo que não necessita de mediação."],"answer":1,"explanation":"A criança é ativa, histórica, social e titular de direitos; aprende nas relações e práticas cotidianas.","trap":"As alternativas erradas oscilam entre passividade e autonomia sem mediação.","review":"Concepção de criança"},{"id":"B02","kind":"Questão autoral","difficulty":"Fácil","topic":"Direitos de aprendizagem","stem":"Qual alternativa contém apenas direitos de aprendizagem e desenvolvimento da Educação Infantil?","options":["Conviver, brincar, participar, explorar, expressar e conhecer-se.","Ler, escrever, calcular, competir, memorizar e avaliar.","Interagir, alfabetizar, disciplinar, promover, classificar e medir.","Cuidar, ensinar, testar, comparar, aprovar e reter."],"answer":0,"explanation":"A lista oficial possui seis verbos: conviver, brincar, participar, explorar, expressar e conhecer-se.","trap":"Inserir verbos pedagogicamente plausíveis, mas que não pertencem à lista.","review":"Seis direitos"},{"id":"B03","kind":"Questão autoral","difficulty":"Médio","topic":"Intencionalidade educativa","stem":"Durante uma brincadeira de mercado, o professor observa negociações, acrescenta embalagens com diferentes tamanhos e registra as estratégias das crianças. Essa atuação demonstra:","options":["controle integral da brincadeira.","intencionalidade educativa sem eliminar o protagonismo infantil.","avaliação classificatória.","antecipação obrigatória de conteúdos matemáticos."],"answer":1,"explanation":"O educador organiza condições e amplia possibilidades, mas a brincadeira continua aberta às iniciativas das crianças.","trap":"Confundir mediação com direção rígida.","review":"Intencionalidade educativa"},{"id":"B04","kind":"Questão autoral","difficulty":"Médio","topic":"Campo EO","stem":"Empatia, identidade, convivência, respeito às diferenças e resolução de conflitos são palavras-chave de qual campo?","options":["O eu, o outro e o nós.","Corpo, gestos e movimentos.","Traços, sons, cores e formas.","Escuta, fala, pensamento e imaginação."],"answer":0,"explanation":"O campo EO concentra experiências de identidade, alteridade, pertencimento, convivência e relações sociais.","trap":"Conflito envolve fala, mas o foco é convivência e relação com o outro.","review":"Campo O eu, o outro e o nós"},{"id":"B05","kind":"Questão autoral","difficulty":"Médio","topic":"Campo ET","stem":"Uma experiência com água, recipientes, comparação de volumes, flutuação e mudanças de estado mobiliza principalmente o campo:","options":["Escuta, fala, pensamento e imaginação.","Espaços, tempos, quantidades, relações e transformações.","O eu, o outro e o nós.","Traços, sons, cores e formas."],"answer":1,"explanation":"Propriedades, quantidades, medidas, fenômenos naturais, relações e transformações são pistas de ET.","trap":"A água pode ser usada em arte, mas o foco do caso é investigação de fenômenos e quantidades.","review":"Campo ET"},{"id":"B06","kind":"Questão autoral","difficulty":"Médio","topic":"Objetivos e atividades","stem":"Assinale a alternativa correta.","options":["Objetivo de aprendizagem é sinônimo de atividade pronta.","Uma mesma atividade pode favorecer diferentes objetivos e campos, conforme a intencionalidade e as experiências das crianças.","Cada objetivo deve ser trabalhado por uma ficha impressa específica.","A numeração dos códigos estabelece hierarquia obrigatória entre os objetivos."],"answer":1,"explanation":"Objetivo indica aprendizagem e desenvolvimento; atividade é uma possibilidade. Os códigos identificam, mas não hierarquizam os objetivos.","trap":"Transformar código em sequência rígida e objetivo em exercício.","review":"Objetivos de aprendizagem"},{"id":"B07","kind":"Questão autoral","difficulty":"Médio","topic":"Inclusão","stem":"Uma criança com deficiência motora participa de uma brincadeira no pátio. A conduta mais adequada é:","options":["retirá-la para uma atividade individual mais simples.","manter a atividade sem adaptações para tratar todos de modo idêntico.","eliminar barreiras, adaptar materiais e assegurar participação com o grupo.","aguardar exclusivamente orientação clínica antes de permitir participação."],"answer":2,"explanation":"Inclusão exige acessibilidade, participação e eliminação de barreiras, não segregação nem igualdade meramente formal.","trap":"Confundir inclusão com atividade paralela ou ausência de adaptação.","review":"Inclusão e acessibilidade"},{"id":"B08","kind":"Questão autoral","difficulty":"Médio","topic":"Rotina","stem":"Sobre a rotina na Educação Infantil, assinale a alternativa correta.","options":["Deve ser rígida para impedir escolhas e imprevistos.","Pode oferecer previsibilidade, mas precisa admitir flexibilidade, escuta e diferentes ritmos.","Deve organizar apenas atividades dirigidas.","É dispensável quando o professor possui experiência."],"answer":1,"explanation":"Rotina combina segurança e previsibilidade com flexibilidade e respeito aos ritmos e interesses das crianças.","trap":"Confundir organização com rigidez.","review":"Rotina, tempos e espaços"},{"id":"B09","kind":"Questão autoral","difficulty":"Médio","topic":"Documentação pedagógica","stem":"A documentação pedagógica serve principalmente para:","options":["produzir ranking entre as crianças.","comprovar que todas fizeram a mesma atividade.","tornar visíveis processos, apoiar reflexão docente e comunicar trajetórias às famílias.","substituir o planejamento anual."],"answer":2,"explanation":"Registros ajudam a interpretar processos, reorganizar experiências e comunicar o trabalho, sem classificar.","trap":"Reduzir documentação a arquivo burocrático ou prova de uniformidade.","review":"Observação e registros"},{"id":"B10","kind":"Questão autoral","difficulty":"Difícil","topic":"Síntese das aprendizagens","stem":"A síntese das aprendizagens esperadas ao fim da Educação Infantil deve ser entendida como:","options":["teste de prontidão obrigatório para ingresso no primeiro ano.","lista de conteúdos mínimos cuja ausência autoriza retenção.","referência balizadora das experiências, sem constituir pré-requisito de acesso ao Ensino Fundamental.","instrumento de comparação pública entre turmas."],"answer":2,"explanation":"A síntese orienta a continuidade e não funciona como seleção, promoção, classificação ou requisito de matrícula.","trap":"Transformar referência pedagógica em exame de prontidão.","review":"Síntese e transição"},{"id":"B11","kind":"Questão autoral","difficulty":"Difícil","topic":"Princípios das DCNEI","stem":"Associe: 1. éticos; 2. políticos; 3. estéticos. ( ) cidadania e criticidade; ( ) sensibilidade e criatividade; ( ) autonomia e solidariedade. A sequência correta é:","options":["1 – 2 – 3.","2 – 3 – 1.","3 – 1 – 2.","2 – 1 – 3."],"answer":1,"explanation":"Políticos = cidadania/criticidade; estéticos = sensibilidade/criatividade; éticos = autonomia/solidariedade.","trap":"Todas as expressões são verdadeiras; a dificuldade é associá-las ao grupo correto.","review":"Princípios das DCNEI"},{"id":"B12","kind":"Questão autoral","difficulty":"Difícil","topic":"Tecnologia e mídias","stem":"Quanto aos recursos tecnológicos e midiáticos na Educação Infantil, é correto afirmar que:","options":["são proibidos pelas DCNEI.","devem substituir experiências corporais, sociais e com a natureza.","podem integrar experiências planejadas, sem reduzir a infância ao consumo passivo de telas.","só podem ser usados para alfabetização formal."],"answer":2,"explanation":"As DCNEI preveem experiências com recursos tecnológicos e midiáticos, integradas a outras linguagens e com intencionalidade.","trap":"Oscilar entre proibição absoluta e uso substitutivo/indiscriminado.","review":"Tecnologia na Educação Infantil"}],"mock":[{"id":"S01","kind":"Minissimulado","difficulty":"Fácil","topic":"Eixos","stem":"Complete: As práticas pedagógicas da Educação Infantil têm como eixos norteadores as ________ e a ________.","options":["competências; avaliação","interações; brincadeira","disciplinas; alfabetização","famílias; escrita"],"answer":1,"explanation":"A formulação correta é interações e brincadeira.","trap":"Troca por conceitos presentes, mas não denominados eixos.","review":"Eixos"},{"id":"S02","kind":"Minissimulado","difficulty":"Fácil","topic":"Direitos","stem":"Qual termo não integra os seis direitos de aprendizagem da Educação Infantil?","options":["Explorar","Participar","Classificar","Conhecer-se"],"answer":2,"explanation":"Classificar não é direito de aprendizagem; é inclusive finalidade rejeitada na avaliação da etapa.","trap":"Palavra comum em experiências matemáticas, mas não na lista dos direitos.","review":"Direitos"},{"id":"S03","kind":"Minissimulado","difficulty":"Médio","topic":"Brincadeira","stem":"Uma brincadeira livre é pedagogicamente compatível com a BNCC quando:","options":["não existe qualquer planejamento do ambiente.","o professor define previamente todas as falas e resultados.","há condições planejadas, possibilidade de escolha e observação atenta.","serve apenas para ocupar o tempo entre atividades."],"answer":2,"explanation":"Livre refere-se à ação e às escolhas das crianças, não à ausência de intencionalidade nas condições oferecidas.","trap":"Oposição falsa entre liberdade e planejamento.","review":"Brincadeira e intencionalidade"},{"id":"S04","kind":"Minissimulado","difficulty":"Médio","topic":"Campos","stem":"Desenho, pintura, modelagem, sons e criação estética apontam principalmente para:","options":["Traços, sons, cores e formas.","O eu, o outro e o nós.","Corpo, gestos e movimentos.","Espaços, tempos, quantidades, relações e transformações."],"answer":0,"explanation":"Essas são pistas típicas de TS.","trap":"Movimento e arte podem se integrar; procure o núcleo do enunciado.","review":"Campo TS"},{"id":"S05","kind":"Minissimulado","difficulty":"Médio","topic":"Código","stem":"No código EI03CG02, o elemento CG identifica:","options":["crianças grandes.","competência geral.","Corpo, gestos e movimentos.","conhecimento geográfico."],"answer":2,"explanation":"CG é a abreviação do campo Corpo, gestos e movimentos.","trap":"Criar expansão intuitiva, mas incorreta, da sigla.","review":"Códigos"},{"id":"S06","kind":"Minissimulado","difficulty":"Médio","topic":"Grupos etários","stem":"Os grupos etários da BNCC devem ser compreendidos:","options":["como limites rígidos de desenvolvimento.","como referências aproximadas, considerando ritmos e singularidades.","como séries escolares com aprovação anual.","como agrupamentos definidos exclusivamente por desempenho."],"answer":1,"explanation":"As faixas organizam objetivos, mas não devem rigidificar os ritmos de aprendizagem e desenvolvimento.","trap":"Converter referência etária em padrão rígido.","review":"Grupos etários"},{"id":"S07","kind":"Minissimulado","difficulty":"Médio","topic":"Cuidado","stem":"A afirmação “o cuidado é indissociável do processo educativo” significa que:","options":["todos os momentos cotidianos podem envolver relações, autonomia e aprendizagens.","o professor deve abandonar o planejamento de experiências.","cuidar substitui brincar e interagir.","higiene e alimentação são atribuições sem valor curricular."],"answer":0,"explanation":"Cuidado e educação integram a experiência da criança.","trap":"Separação assistencialista entre corpo e aprendizagem.","review":"Cuidar e educar"},{"id":"S08","kind":"Minissimulado","difficulty":"Médio","topic":"Avaliação","stem":"Assinale a prática inadequada de avaliação na Educação Infantil.","options":["Observação crítica das brincadeiras.","Uso de portfólios e relatórios.","Registro de trajetórias e reorganização do planejamento.","Retenção da criança por não atingir padrões de prontidão."],"answer":3,"explanation":"Não há retenção na Educação Infantil; avaliação não seleciona nem promove.","trap":"Usar prontidão como justificativa para retenção.","review":"Avaliação"},{"id":"S09","kind":"Minissimulado","difficulty":"Médio","topic":"DCNEI","stem":"Nas DCNEI, currículo é entendido como:","options":["lista fixa de disciplinas e conteúdos.","conjunto de práticas que articula experiências e saberes infantis com patrimônios culturais e conhecimentos.","material didático adotado pela rede.","sequência de exercícios preparatórios para o Fundamental."],"answer":1,"explanation":"Currículo é conjunto de práticas articuladoras, orientado ao desenvolvimento integral.","trap":"Reduzir currículo a lista, livro ou preparação.","review":"Definições das DCNEI"},{"id":"S10","kind":"Minissimulado","difficulty":"Médio","topic":"Princípios","stem":"Sensibilidade, criatividade, ludicidade e liberdade de expressão integram os princípios:","options":["éticos.","políticos.","estéticos.","econômicos."],"answer":2,"explanation":"Esses termos pertencem ao princípio estético.","trap":"Associar estético somente a técnica artística.","review":"Princípios"},{"id":"S11","kind":"Minissimulado","difficulty":"Difícil","topic":"Transição","stem":"A continuidade entre Educação Infantil e Ensino Fundamental é favorecida principalmente por:","options":["provas de seleção e turmas por desempenho.","antecipação do currículo do primeiro ano.","acolhimento, diálogo entre profissionais e uso de registros das trajetórias.","abandono da brincadeira no último ano da pré-escola."],"answer":2,"explanation":"Continuidade não é antecipação; envolve acolhimento, troca de informações e respeito às especificidades.","trap":"Confundir preparar com escolarizar antecipadamente.","review":"Transição"},{"id":"S12","kind":"Minissimulado","difficulty":"Difícil","topic":"Inclusão","stem":"Garantir acessibilidade de espaços, materiais, brinquedos e instruções é uma exigência relacionada a:","options":["participação inclusiva e eliminação de barreiras.","segregação por tipo de deficiência.","dispensa de objetivos de aprendizagem.","substituição do convívio coletivo por atendimento individual."],"answer":0,"explanation":"Acessibilidade sustenta participação e pertencimento no grupo.","trap":"Tratar adaptação como segregação ou redução de expectativas.","review":"Inclusão"},{"id":"S13","kind":"Minissimulado","difficulty":"Difícil","topic":"Situação prática","stem":"Duas crianças disputam um brinquedo. A intervenção mais coerente é:","options":["retirar o brinquedo e encerrar o conflito sem escuta.","punir ambas para evitar novas disputas.","ajudar a nomear sentimentos, ouvir versões e construir estratégias de negociação.","não intervir em nenhuma circunstância."],"answer":2,"explanation":"Conflitos são oportunidades de aprendizagem social, com mediação proporcional à situação.","trap":"Escolher entre controle autoritário e omissão total.","review":"Mediação de conflitos"},{"id":"S14","kind":"Minissimulado","difficulty":"Difícil","topic":"Objetivos","stem":"A numeração final de um código da BNCC indica:","options":["uma ordem obrigatória de ensino.","a posição sequencial do objetivo no campo e grupo, sem hierarquia pedagógica.","o nível de dificuldade da atividade.","a idade exata da criança em meses."],"answer":1,"explanation":"A numeração identifica a posição; não estabelece hierarquia nem ordem obrigatória.","trap":"Ler sequência como progressão rígida.","review":"Códigos"},{"id":"S15","kind":"Minissimulado","difficulty":"Difícil","topic":"Integração curricular","stem":"Em uma dramatização de feira, crianças negociam papéis, contam objetos, criam placas e movimentam-se pelo espaço. A leitura mais adequada é:","options":["A atividade pertence exclusivamente ao campo O eu, o outro e o nós.","A atividade mobiliza de forma articulada diferentes direitos, objetivos e campos de experiências.","A atividade não possui intencionalidade por ser brincadeira.","A atividade só é válida se terminar com uma ficha escrita individual."],"answer":1,"explanation":"Experiências complexas integram campos, linguagens e direitos; não são compartimentos estanques.","trap":"Exclusividade de campo e exigência de produto escolarizado.","review":"Integração dos campos"}],"ldbadapted":[{"id":"LDA01","kind":"Questão adaptada","difficulty":"Fácil","topic":"Arts. 12 e 13","stem":"À luz da LDB, assinale a alternativa que descreve corretamente a relação entre proposta pedagógica e trabalho docente.","options":["A escola apenas homologa uma proposta feita individualmente pelo professor.","O professor recebe da gestão um plano de trabalho pronto e deve apenas executá-lo.","O professor participa da elaboração da proposta pedagógica e elabora seu plano de trabalho em consonância com ela.","Somente o Município pode elaborar a proposta pedagógica de cada escola."],"answer":2,"explanation":"O art. 12 atribui à escola a elaboração e execução da proposta pedagógica; o art. 13 manda o docente participar dessa elaboração e elaborar/cumprir seu plano de trabalho segundo a proposta.","review":"Arts. 12 e 13"},{"id":"LDA02","kind":"Questão adaptada","difficulty":"Fácil","topic":"Art. 24","stem":"Nos níveis fundamental e médio, a frequência mínima exigida pelo art. 24 da LDB para aprovação é de:","options":["60%","70%","75%","80%"],"answer":2,"explanation":"O art. 24, VI, exige 75% do total de horas letivas para aprovação. Não confunda com os 60% da pré-escola no art. 31.","review":"Frequência: art. 24 × art. 31"},{"id":"LDA03","kind":"Questão adaptada","difficulty":"Fácil","topic":"Art. 21","stem":"Segundo a LDB, a Educação Básica é formada por:","options":["Educação Infantil, Ensino Fundamental e Ensino Médio.","Ensino Fundamental, Ensino Médio e Educação Superior.","Educação Infantil e Ensino Fundamental apenas.","Educação Infantil, Ensino Fundamental, Ensino Médio e Educação Superior."],"answer":0,"explanation":"O art. 21 separa educação escolar em Educação Básica e Educação Superior; a Básica reúne EI, EF e EM.","review":"Art. 21"},{"id":"LDA04","kind":"Questão adaptada","difficulty":"Fácil","topic":"Art. 31","stem":"Na educação pré-escolar, o controle de frequência exige, no mínimo:","options":["50% do total de horas.","60% do total de horas.","70% do total de horas.","75% do total de horas."],"answer":1,"explanation":"Art. 31, IV: frequência mínima de 60% do total de horas na pré-escola.","review":"Art. 31"},{"id":"LDA05","kind":"Questão adaptada","difficulty":"Fácil","topic":"Art. 30","stem":"Assinale a distribuição etária correta prevista no art. 30.","options":["Creche: até 2; pré-escola: 3 a 5.","Creche: até 3; pré-escola: 4 e 5.","Creche: 0 a 4; pré-escola: 5.","Creche: até 3; pré-escola: 4 a 6."],"answer":1,"explanation":"A LDB define creches ou equivalentes para crianças de até 3 anos e pré-escolas para 4 e 5 anos.","review":"Art. 30"},{"id":"LDA06","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 29","stem":"Qual conjunto corresponde aos aspectos do desenvolvimento integral expressamente citados no art. 29?","options":["Físico, psicológico, intelectual e social.","Motor, moral, acadêmico e profissional.","Cognitivo, esportivo, produtivo e social.","Físico, religioso, intelectual e laboral."],"answer":0,"explanation":"A redação do art. 29 enumera físico, psicológico, intelectual e social.","review":"Art. 29"},{"id":"LDA07","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 11 — 2026","stem":"Após alteração de 2026, a incumbência municipal de ofertar Educação Infantil explicita:","options":["apenas zonas urbanas, pela maior densidade.","zonas urbanas e rurais, na proporção da distribuição populacional.","somente zonas rurais sem oferta estadual.","apenas pré-escola; creche permanece atribuição estadual."],"answer":1,"explanation":"Lei 15.369/2026: art. 11, V, passou a mencionar creches e pré-escolas nas zonas urbanas e rurais, proporcionalmente à distribuição populacional.","review":"Art. 11, V — atualização 2026"},{"id":"LDA08","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 61 §2 — 2026","stem":"A designação formal do cargo é requisito para o enquadramento previsto no art. 61 §2?","options":["Sim. O cargo deve chamar-se Professor de Educação Infantil.","Sim, salvo autorização da Secretaria de Educação.","Não. A lei diz independentemente da designação do cargo, desde que os demais requisitos sejam cumpridos.","Não, e nenhum requisito de formação ou concurso é exigido."],"answer":2,"explanation":"A novidade de 2026 afasta a exigência do nome do cargo, mas mantém função docente direta, formação e aprovação em concurso público.","review":"Art. 61 §2"},{"id":"LDA09","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 62","stem":"A formação mínima admitida pela LDB para o magistério na Educação Infantil é:","options":["qualquer ensino médio.","nível médio na modalidade Normal.","curso técnico administrativo.","bacharelado em qualquer área."],"answer":1,"explanation":"O art. 62 admite, como formação mínima para EI e cinco primeiros anos do EF, nível médio na modalidade Normal.","review":"Art. 62"},{"id":"LDA10","kind":"Questão adaptada","difficulty":"Fácil","topic":"Arts. 4º e 6º","stem":"A educação básica obrigatória e gratuita e o dever dos responsáveis de matrícula iniciam, respectivamente:","options":["0 anos e 0 anos.","4 anos e 4 anos.","5 anos e 5 anos.","6 anos e 6 anos."],"answer":1,"explanation":"A obrigatoriedade vai dos 4 aos 17 anos; os responsáveis devem matricular a partir dos 4 anos.","review":"Arts. 4º e 6º"},{"id":"LDA11","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 12 VIII","stem":"A escola deve notificar o Conselho Tutelar quando o aluno apresenta faltas:","options":["acima de 30% do percentual permitido em lei.","acima de 30% do ano letivo, necessariamente.","acima de 50% do percentual permitido em lei.","em qualquer quantidade, obrigatoriamente no primeiro dia."],"answer":0,"explanation":"A redação vigente do art. 12, VIII, a, usa “acima de 30% do percentual permitido em lei”.","review":"Art. 12, VIII"},{"id":"LDA12","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 14","stem":"A gestão democrática do ensino público na Educação Básica observa, entre outros, o princípio de:","options":["participação apenas do diretor na proposta pedagógica.","participação dos profissionais da educação no projeto pedagógico e das comunidades escolar/local em Conselhos e Fóruns.","participação das famílias apenas em assuntos financeiros.","gestão democrática obrigatória do ensino privado."],"answer":1,"explanation":"São os dois princípios centrais do art. 14.","review":"Art. 14"},{"id":"LDA13","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 3º","stem":"Assinale a expressão que NÃO corresponde a um princípio vigente do art. 3º.","options":["Igualdade de condições para acesso e permanência.","Respeito à liberdade e apreço à tolerância.","Gestão democrática do ensino público.","Uniformidade obrigatória de concepções pedagógicas."],"answer":3,"explanation":"A LDB prevê pluralismo de ideias e concepções pedagógicas, não uniformidade.","review":"Art. 3º"},{"id":"LDA14","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 31","stem":"A avaliação na Educação Infantil, segundo a LDB, deve:","options":["classificar para acesso ao Ensino Fundamental.","acompanhar e registrar o desenvolvimento, sem objetivo de promoção.","ser baseada prioritariamente em provas finais.","definir retenção quando a criança não atingir metas."],"answer":1,"explanation":"Art. 31, I: acompanhamento e registro, sem objetivo de promoção, mesmo para acesso ao EF.","review":"Art. 31 — avaliação"},{"id":"LDA15","kind":"Questão adaptada","difficulty":"Difícil","topic":"Art. 13","stem":"Qual item NÃO é incumbência do docente segundo o art. 13?","options":["Zelar pela aprendizagem dos alunos.","Estabelecer estratégias de recuperação.","Administrar os recursos materiais e financeiros da escola.","Colaborar com a articulação escola-família-comunidade."],"answer":2,"explanation":"Administrar recursos materiais e financeiros é incumbência do estabelecimento de ensino no art. 12.","review":"Art. 12 × 13"}],"ldbauthorial":[{"id":"LDU01","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 31 — números","stem":"Uma pré-escola oferece 800 horas anuais em 200 dias. Segundo a LDB, a afirmação é:","options":["incompatível, pois exige 1.000 horas.","compatível com o mínimo legal.","incompatível, pois exige 220 dias.","compatível apenas para Ensino Fundamental."],"answer":1,"explanation":"Na EI, art. 31: mínimo de 800 horas em pelo menos 200 dias de trabalho educacional.","review":"Art. 31"},{"id":"LDU02","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 31 — jornada","stem":"A jornada integral na Educação Infantil deve ter, no mínimo:","options":["4 horas.","5 horas.","6 horas.","7 horas."],"answer":3,"explanation":"Art. 31, III: 4 horas no parcial e 7 horas na jornada integral.","review":"Art. 31"},{"id":"LDU03","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 12 × 13","stem":"Uma diretora afirma que somente a gestão participa da proposta pedagógica e que professores recebem seus planos prontos. À luz da LDB:","options":["a afirmação está correta.","a escola elabora/executa a proposta e o docente participa de sua elaboração e faz seu plano conforme ela.","o Município faz tanto a proposta quanto o plano de cada professor.","a proposta pedagógica é opcional."],"answer":1,"explanation":"A situação viola a articulação dos arts. 12 e 13.","review":"Arts. 12 e 13"},{"id":"LDU04","kind":"Questão autoral","difficulty":"Difícil","topic":"Art. 11 — 2026","stem":"Assinale a alternativa correta sobre a prioridade municipal.","options":["O Município prioriza o Ensino Médio.","O Município oferece EI e, com prioridade, Ensino Fundamental.","O Município somente oferece creche, nunca pré-escola.","O Município só atua na área rural."],"answer":1,"explanation":"Art. 11, V: EI em creches/pré-escolas e prioridade ao EF.","review":"Art. 11"},{"id":"LDU05","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 25-A","stem":"Qual item NÃO integra a lista de condições mínimas trazida pelo art. 25-A?","options":["Acesso à internet.","Instalações acessíveis.","Abastecimento de água tratada.","Piscina semiolímpica obrigatória."],"answer":3,"explanation":"O art. 25-A não exige piscina; lista biblioteca, laboratórios, internet, quadra coberta, cozinha, refeitório, banheiros, acessibilidade e saneamento, entre outros.","review":"Art. 25-A"},{"id":"LDU06","kind":"Questão autoral","difficulty":"Difícil","topic":"Art. 26 — 2026","stem":"Em julho de 2026, a LDB recebeu previsão de componente curricular obrigatório relacionado a:","options":["educação política e direitos da cidadania.","educação automobilística.","programação avançada na creche.","empreendedorismo obrigatório em toda EI."],"answer":0,"explanation":"Lei 15.468/2026 incluiu o §9º-B no art. 26.","review":"Art. 26 — atualização 2026"},{"id":"LDU07","kind":"Questão autoral","difficulty":"Difícil","topic":"Art. 58","stem":"A expressão legal sobre a oferta da Educação Especial é:","options":["exclusivamente na rede especial.","preferencialmente na rede regular de ensino.","somente em instituição privada conveniada.","obrigatoriamente fora da escola comum."],"answer":1,"explanation":"“Preferencialmente” é a palavra-chave legal.","review":"Art. 58"},{"id":"LDU08","kind":"Questão autoral","difficulty":"Difícil","topic":"Educação Bilíngue de Surdos","stem":"Segundo a LDB, a Educação Bilíngue de Surdos pode iniciar-se:","options":["somente no Ensino Fundamental.","aos 4 anos.","ao zero ano, na Educação Infantil.","apenas após alfabetização em português."],"answer":2,"explanation":"A modalidade pode iniciar-se ao zero ano na EI e se estender ao longo da vida.","review":"Arts. 60-A e 60-B"},{"id":"LDU09","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 67 — 2026","stem":"Após alteração de 2026, o aperfeiçoamento profissional continuado pode compreender expressamente:","options":["apenas cursos livres sem certificação.","qualificação, pós-graduação lato/stricto sensu e período para pesquisa em educação.","somente licença não remunerada.","apenas formação inicial."],"answer":1,"explanation":"Lei 15.462/2026 detalhou essas atividades no art. 67, II.","review":"Art. 67"},{"id":"LDU10","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 4º — 2025","stem":"Qual garantia foi acrescentada ao dever do Estado em 2025?","options":["Água potável e infraestrutura física e sanitária adequadas.","Transporte aéreo escolar.","Uniforme obrigatório gratuito.","Tablet individual para toda criança."],"answer":0,"explanation":"Art. 4º, XIII, incluído pela Lei 15.276/2025.","review":"Art. 4º, XIII"},{"id":"LDU11","kind":"Questão autoral","difficulty":"Difícil","topic":"Art. 23","stem":"O calendário escolar pode adequar-se a peculiaridades locais:","options":["reduzindo livremente as horas previstas.","inclusive climáticas e econômicas, sem reduzir o número de horas letivas previsto.","somente com autorização federal individual.","apenas no Ensino Superior."],"answer":1,"explanation":"Art. 23 §2 preserva o número de horas letivas.","review":"Art. 23"},{"id":"LDU12","kind":"Questão autoral","difficulty":"Médio","topic":"Sistemas de ensino","stem":"Uma instituição privada de Educação Infantil localizada em um Município integra, em regra:","options":["o sistema federal.","o sistema municipal de ensino.","sempre o sistema estadual.","nenhum sistema de ensino."],"answer":1,"explanation":"Art. 18 inclui instituições de EI criadas e mantidas pela iniciativa privada no sistema municipal.","review":"Art. 18"},{"id":"LDU13","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 27","stem":"Entre as diretrizes dos conteúdos curriculares da Educação Básica está:","options":["desporto educacional e apoio às práticas desportivas não formais.","substituição da cidadania por treinamento profissional exclusivo.","desconsideração das condições de escolaridade dos alunos.","proibição de temas sociais."],"answer":0,"explanation":"É o art. 27, IV; o artigo também traz valores sociais, condições de escolaridade e orientação para o trabalho.","review":"Art. 27"},{"id":"LDU14","kind":"Questão autoral","difficulty":"Difícil","topic":"Art. 61 §2","stem":"Qual conjunto atende integralmente ao art. 61 §2?","options":["Atuação administrativa + qualquer ensino médio + contratação temporária.","Função docente direta com crianças + formação no magistério ou superior + aprovação em concurso público.","Função docente + ausência de formação + indicação política.","Cargo chamado professor, independentemente da função exercida."],"answer":1,"explanation":"São os requisitos expressos da norma de 2026.","review":"Art. 61 §2"},{"id":"LDU15","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 5º","stem":"O acesso à educação básica obrigatória é:","options":["favor administrativo sem exigibilidade.","direito público subjetivo.","direito apenas do Ensino Fundamental.","dever exclusivo da família sem obrigação estatal."],"answer":1,"explanation":"Art. 5º: educação básica obrigatória é direito público subjetivo, podendo ser exigida do poder público.","review":"Art. 5º"}],"ldbmock":[{"id":"LDM01","kind":"Simulado Rank 2","difficulty":"Fácil","topic":"Art. 29","stem":"A Educação Infantil é:","options":["modalidade complementar.","primeira etapa da Educação Básica.","primeira etapa da Educação Superior.","etapa opcional sem finalidade educacional."],"answer":1,"explanation":"Art. 29.","review":"Art. 29"},{"id":"LDM02","kind":"Simulado Rank 2","difficulty":"Médio","topic":"Art. 13","stem":"É incumbência do docente:","options":["administrar recursos financeiros da escola.","elaborar e cumprir plano de trabalho segundo a proposta pedagógica.","autorizar estabelecimentos do sistema.","instituir Conselho Tutelar."],"answer":1,"explanation":"Art. 13, II.","review":"Art. 13"},{"id":"LDM03","kind":"Simulado Rank 2","difficulty":"Médio","topic":"Art. 12","stem":"É incumbência da escola:","options":["zelar pela aprendizagem como atribuição exclusiva da direção.","administrar pessoal e recursos materiais e financeiros.","elaborar o PNE.","oferecer Ensino Médio com prioridade."],"answer":1,"explanation":"Art. 12, II.","review":"Art. 12"},{"id":"LDM04","kind":"Simulado Rank 2","difficulty":"Fácil","topic":"Art. 30","stem":"Uma criança de 5 anos encontra-se, pela organização da LDB, na:","options":["creche.","pré-escola.","Educação Superior.","EJA."],"answer":1,"explanation":"Pré-escola: 4 e 5 anos.","review":"Art. 30"},{"id":"LDM05","kind":"Simulado Rank 2","difficulty":"Médio","topic":"Art. 31","stem":"Assinale a opção correta.","options":["A EI promove para acesso ao EF.","A EI exige 75% de frequência para todas as crianças.","A avaliação acompanha e registra o desenvolvimento sem promoção.","A jornada integral mínima é 6h."],"answer":2,"explanation":"Art. 31, I.","review":"Art. 31"},{"id":"LDM06","kind":"Simulado Rank 2","difficulty":"Médio","topic":"Art. 31","stem":"O conjunto correto é:","options":["800h; 200 dias; 4h parcial; 7h integral.","1.000h; 200 dias; 5h parcial; 8h integral.","800h; 180 dias; 4h parcial; 6h integral.","600h; 200 dias; 4h parcial; 7h integral."],"answer":0,"explanation":"Art. 31, II e III.","review":"Art. 31 — números"},{"id":"LDM07","kind":"Simulado Rank 2","difficulty":"Médio","topic":"Frequência","stem":"Qual associação está correta?","options":["Pré-escola 75%; EF/EM 60%.","Pré-escola 60%; EF/EM 75%.","Todos os níveis 75%.","Todos os níveis 60%."],"answer":1,"explanation":"Art. 31 IV × art. 24 VI.","review":"Frequência"},{"id":"LDM08","kind":"Simulado Rank 2","difficulty":"Médio","topic":"Art. 11","stem":"Em 2026, o art. 11 passou a explicitar oferta municipal de EI:","options":["só em zona urbana.","em zonas urbana e rural proporcionalmente à população.","só onde não existe Ensino Fundamental.","apenas em pré-escolas privadas."],"answer":1,"explanation":"Lei 15.369/2026.","review":"Art. 11 — 2026"},{"id":"LDM09","kind":"Simulado Rank 2","difficulty":"Difícil","topic":"Art. 61 §2","stem":"A frase correta é:","options":["o nome do cargo define sozinho quem é professor da EI.","a lei ignora formação e concurso.","a designação do cargo não impede o enquadramento quando função, atuação, formação e concurso atendem à lei.","somente licenciados em Pedagogia podem ser considerados pela norma, sem outra hipótese."],"answer":2,"explanation":"Art. 61 §2.","review":"Art. 61 §2"},{"id":"LDM10","kind":"Simulado Rank 2","difficulty":"Fácil","topic":"Art. 2º","stem":"A finalidade tripla da educação inclui:","options":["pleno desenvolvimento, cidadania e qualificação para o trabalho.","memorização, seleção e competição.","formação religiosa, militar e produtiva.","somente qualificação profissional."],"answer":0,"explanation":"Art. 2º.","review":"Art. 2º"},{"id":"LDM11","kind":"Simulado Rank 2","difficulty":"Médio","topic":"Art. 3º","stem":"Qual é princípio da LDB?","options":["Pluralismo de ideias e concepções pedagógicas.","Uniformidade ideológica obrigatória.","Apreço à intolerância.","Gestão democrática obrigatória do ensino privado."],"answer":0,"explanation":"Art. 3º.","review":"Art. 3º"},{"id":"LDM12","kind":"Simulado Rank 2","difficulty":"Médio","topic":"Arts. 4º e 6º","stem":"Assinale a correta.","options":["A obrigatoriedade começa aos 0 anos.","A matrícula pelos responsáveis é dever a partir dos 4 anos.","A pré-escola não integra a faixa obrigatória.","A Educação Infantil só é gratuita a partir de 4 anos."],"answer":1,"explanation":"Obrigatória 4–17; EI gratuita até 5.","review":"Arts. 4º e 6º"},{"id":"LDM13","kind":"Simulado Rank 2","difficulty":"Médio","topic":"Art. 14","stem":"Gestão democrática envolve:","options":["somente direção escolar.","profissionais da educação no projeto e comunidades nos Conselhos/Fóruns.","somente pais, sem profissionais.","gestão democrática do ensino privado por lei federal."],"answer":1,"explanation":"Art. 14 I e II.","review":"Art. 14"},{"id":"LDM14","kind":"Simulado Rank 2","difficulty":"Difícil","topic":"Art. 12 VIII","stem":"A escola notifica o Conselho Tutelar, entre outras hipóteses, sobre:","options":["faltas acima de 30% do percentual permitido e dados de violência envolvendo alunos.","qualquer nota abaixo da média.","todo atraso de 5 minutos.","apenas casos de violência praticados por adultos externos."],"answer":0,"explanation":"Redação atual do art. 12 VIII.","review":"Art. 12 VIII"},{"id":"LDM15","kind":"Simulado Rank 2","difficulty":"Médio","topic":"Art. 21","stem":"A Educação Superior:","options":["integra a Educação Básica.","é nível distinto da Educação Básica na composição da educação escolar.","é modalidade da Educação Infantil.","substitui o Ensino Médio."],"answer":1,"explanation":"Art. 21 separa Educação Básica e Educação Superior.","review":"Art. 21"},{"id":"LDM16","kind":"Simulado Rank 2","difficulty":"Difícil","topic":"Art. 25-A","stem":"A condição mínima criada em 2026 aplica-se:","options":["a todas as escolas públicas de Educação Básica, respeitadas as especificidades.","somente às universidades federais.","somente às escolas privadas.","somente à pré-escola urbana."],"answer":0,"explanation":"Art. 25-A.","review":"Art. 25-A"},{"id":"LDM17","kind":"Simulado Rank 2","difficulty":"Médio","topic":"Art. 58","stem":"A Educação Especial é oferecida:","options":["preferencialmente na rede regular de ensino.","exclusivamente em classe especial.","apenas após o Ensino Fundamental.","somente mediante decisão judicial."],"answer":0,"explanation":"Art. 58.","review":"Art. 58"},{"id":"LDM18","kind":"Simulado Rank 2","difficulty":"Médio","topic":"Art. 62","stem":"Para EI, a formação mínima admitida é:","options":["ensino médio comum.","nível médio, modalidade Normal.","ensino fundamental completo.","curso livre de recreação."],"answer":1,"explanation":"Art. 62.","review":"Art. 62"},{"id":"LDM19","kind":"Simulado Rank 2","difficulty":"Difícil","topic":"Art. 67","stem":"A LDB inclui na valorização dos profissionais:","options":["período reservado a estudos, planejamento e avaliação incluído na carga de trabalho.","planejamento apenas fora da carga.","ingresso por indicação política como regra.","ausência de plano de carreira."],"answer":0,"explanation":"Art. 67.","review":"Art. 67"},{"id":"LDM20","kind":"Simulado Rank 2","difficulty":"Difícil","topic":"Art. 23","stem":"A adequação do calendário às peculiaridades locais:","options":["pode reduzir livremente horas letivas.","não pode reduzir o número de horas letivas previsto em lei.","é proibida em qualquer situação.","depende de autorização do Congresso Nacional."],"answer":1,"explanation":"Art. 23 §2.","review":"Art. 23"}],"ecaadapted":[{"id":"EA01","kind":"Questão adaptada","difficulty":"Fácil","topic":"Art. 2º","stem":"Segundo o ECA, assinale a alternativa correta sobre as faixas etárias.","options":["Criança é a pessoa até 12 anos completos; adolescente, dos 13 aos 18.","Criança é a pessoa até 12 anos incompletos; adolescente, entre 12 e 18 anos.","Criança é a pessoa até 11 anos; adolescente, entre 11 e 18 anos.","O ECA não estabelece critério etário."],"answer":1,"explanation":"O art. 2º usa a expressão “até doze anos de idade incompletos” e considera adolescente a pessoa entre 12 e 18 anos.","trap":"Trocar “incompletos” por “completos”.","review":"Art. 2º"},{"id":"EA02","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 4º","stem":"A garantia de prioridade absoluta compreende todas as opções abaixo, EXCETO:","options":["Primazia de proteção e socorro.","Precedência de atendimento em serviços públicos ou de relevância pública.","Preferência na formulação e execução de políticas sociais públicas.","Exclusividade de acesso a todo e qualquer serviço público, independentemente da situação."],"answer":3,"explanation":"O ECA enumera primazia, precedência, preferência e destinação privilegiada de recursos; não estabelece exclusividade indiscriminada.","trap":"Transformar prioridade em exclusividade absoluta.","review":"Art. 4º"},{"id":"EA03","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 18-A","stem":"Para o ECA, castigo físico é:","options":["Qualquer bronca verbal dirigida à criança.","Ação disciplinar ou punitiva com uso de força física que resulte em sofrimento físico ou lesão.","Somente agressão que produza lesão comprovada por laudo.","Apenas conduta praticada por pai ou mãe."],"answer":1,"explanation":"A definição exige força física e resultado de sofrimento físico ou lesão; não exige laudo nem se restringe aos pais.","trap":"Apagar o “ou” entre sofrimento e lesão.","review":"Art. 18-A"},{"id":"EA04","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 18-A","stem":"Assinale a conduta que se enquadra na definição legal de tratamento cruel ou degradante.","options":["Apenas contato físico que cause hematoma.","Humilhar, ameaçar gravemente ou ridicularizar a criança ou o adolescente.","Discordar educadamente da criança.","Aplicar regra pedagógica proporcional e respeitosa."],"answer":1,"explanation":"O ECA define tratamento cruel/degradante por humilhação, ameaça grave ou ridicularização.","trap":"Exigir agressão corporal para reconhecer a violação.","review":"Art. 18-A"},{"id":"EA05","kind":"Questão adaptada","difficulty":"Fácil","topic":"Art. 13","stem":"A comunicação ao Conselho Tutelar prevista no art. 13 é obrigatória quando houver:","options":["Apenas confirmação judicial de maus-tratos.","Somente confissão do responsável.","Suspeita ou confirmação de castigo físico, tratamento cruel/degradante ou maus-tratos.","Apenas lesão física grave."],"answer":2,"explanation":"A lei utiliza “suspeita ou confirmação”; o dever não depende de certeza judicial.","trap":"Trocar suspeita por confirmação.","review":"Art. 13"},{"id":"EA06","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 53","stem":"Constitui direito educacional previsto no ECA:","options":["Ser impedido de recorrer contra critérios avaliativos.","Ser respeitado por seus educadores.","Frequentar apenas escola escolhida livremente pelo poder público, sem critério territorial.","Excluir a família do processo pedagógico."],"answer":1,"explanation":"O art. 53 assegura o direito de ser respeitado por seus educadores e também outros direitos de acesso, avaliação e participação.","trap":"Negar direitos expressos trocando o verbo.","review":"Art. 53"},{"id":"EA07","kind":"Questão adaptada","difficulty":"Fácil","topic":"Art. 54","stem":"O ECA estabelece como dever do Estado o atendimento em creche e pré-escola:","options":["De zero a três anos apenas.","De quatro a seis anos.","Às crianças de zero a cinco anos.","Somente quando houver decisão judicial."],"answer":2,"explanation":"O art. 54, IV, usa a faixa de zero a cinco anos.","trap":"Usar redação antiga de zero a seis anos.","review":"Art. 54"},{"id":"EA08","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 56","stem":"Qual alternativa NÃO integra a lista do art. 56 para comunicação ao Conselho Tutelar por dirigentes do ensino fundamental?","options":["Maus-tratos envolvendo alunos.","Reiteração de faltas injustificadas e evasão, esgotados os recursos escolares.","Elevados níveis de repetência.","Indisciplina ocasional durante uma atividade."],"answer":3,"explanation":"Indisciplina ocasional não está na lista legal. A redação atual também inclui negligência, abuso ou abandono.","trap":"Inserir um problema escolar plausível, mas não previsto no artigo.","review":"Art. 56"},{"id":"EA09","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 19","stem":"Assinale a combinação correta sobre acolhimento.","options":["Reavaliação a cada 6 meses e permanência máxima de 24 meses.","Reavaliação no máximo a cada 3 meses e permanência institucional, como regra, não superior a 18 meses.","Reavaliação anual e permanência sem limite.","Reavaliação mensal e permanência máxima de 12 meses."],"answer":1,"explanation":"O art. 19 prevê reavaliação no máximo a cada 3 meses e regra de permanência institucional de até 18 meses, salvo necessidade fundamentada no superior interesse.","trap":"Misturar prazos de redações antigas.","review":"Art. 19"},{"id":"EA10","kind":"Questão adaptada","difficulty":"Fácil","topic":"Art. 23","stem":"A falta ou carência de recursos materiais:","options":["É motivo suficiente para perda do poder familiar.","É motivo suficiente para suspensão automática do poder familiar.","Não constitui motivo suficiente, por si só, para perda ou suspensão do poder familiar.","Obriga imediatamente a colocação em família substituta."],"answer":2,"explanation":"O art. 23 rejeita expressamente a pobreza como fundamento suficiente isolado.","trap":"Confundir vulnerabilidade econômica com abandono jurídico.","review":"Art. 23"},{"id":"EA11","kind":"Questão adaptada","difficulty":"Fácil","topic":"Art. 28","stem":"A colocação em família substituta ocorre mediante:","options":["Guarda, tutela ou adoção.","Acolhimento, internação ou advertência.","Curatela, emancipação ou guarda.","Somente adoção."],"answer":0,"explanation":"O art. 28 reúne guarda, tutela e adoção.","trap":"Misturar medidas protetivas com formas de família substituta.","review":"Art. 28"},{"id":"EA12","kind":"Questão adaptada","difficulty":"Médio","topic":"Art. 98","stem":"As medidas de proteção são aplicáveis quando direitos forem ameaçados ou violados:","options":["Somente por ação do Estado.","Por ação/omissão da sociedade ou Estado; falta/omissão/abuso dos pais ou responsável; ou em razão da própria conduta.","Apenas por crime praticado por adulto.","Somente após decisão penal definitiva."],"answer":1,"explanation":"O art. 98 organiza exatamente três hipóteses de incidência.","trap":"Reduzir o sistema protetivo à ocorrência de crime.","review":"Art. 98"},{"id":"EA13","kind":"Questão adaptada","difficulty":"Fácil","topic":"Art. 131","stem":"O Conselho Tutelar é:","options":["Órgão jurisdicional integrante do Poder Judiciário.","Órgão permanente e autônomo, não jurisdicional, encarregado de zelar pelos direitos.","Órgão temporário subordinado ao Ministério Público.","Entidade privada sem função pública."],"answer":1,"explanation":"Esta é a caracterização nuclear do art. 131.","trap":"Trocar “não jurisdicional” por “jurisdicional”.","review":"Art. 131"},{"id":"EA14","kind":"Questão adaptada","difficulty":"Médio","topic":"Arts. 132–133","stem":"Sobre o Conselho Tutelar, assinale a correta.","options":["É composto por 3 membros para mandato de 2 anos.","É composto por 5 membros para mandato de 4 anos; entre os requisitos está idade superior a 21 anos.","É composto por 7 membros vitalícios.","A idade mínima nacional é 18 anos."],"answer":1,"explanation":"O texto atual prevê 5 membros, mandato de 4 anos e requisito de idade superior a 21 anos.","trap":"Usar números intuitivos ou redações antigas.","review":"Arts. 132–133"},{"id":"EA15","kind":"Questão adaptada","difficulty":"Fácil","topic":"Art. 137","stem":"As decisões do Conselho Tutelar somente poderão ser revistas:","options":["Pelo Ministério Público, de ofício.","Pela autoridade judiciária, a pedido de quem tenha legítimo interesse.","Pelo diretor da escola.","Pela Câmara Municipal."],"answer":1,"explanation":"É a redação essencial do art. 137, já cobrada pela UniFil.","trap":"Confundir fiscalização/atuação do MP com revisão das decisões do CT.","review":"Art. 137"}],"ecaauthorial":[{"id":"EC01","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 13","stem":"Uma educadora observa sinais compatíveis com maus-tratos, mas não possui confirmação. À luz do ECA, a conduta juridicamente mais adequada é:","options":["Aguardar confirmação definitiva antes de qualquer providência.","Tratar a situação como possível violação e seguir o dever de comunicação/protocolo protetivo, pois a lei alcança suspeita.","Interrogar a criança repetidamente até obter confissão.","Publicar o caso em grupo de mensagens para obter opiniões."],"answer":1,"explanation":"O art. 13 não condiciona a comunicação à certeza; suspeita já está contemplada.","trap":"Exigir prova é uma forma comum de inverter a lógica protetiva.","review":"Art. 13"},{"id":"EC02","kind":"Questão autoral","difficulty":"Médio","topic":"Arts. 17–18-A","stem":"Um adulto chama repetidamente uma criança de “burra” diante do grupo para discipliná-la. Não há contato físico. A melhor leitura é:","options":["Sem contato físico não há violação relevante ao ECA.","Pode configurar tratamento cruel/degradante por humilhação ou ridicularização, além de violar respeito e dignidade.","É castigo físico obrigatoriamente.","É permitido se houver finalidade educativa."],"answer":1,"explanation":"Humilhação e ridicularização entram na definição de tratamento cruel/degradante, independentemente de força física.","trap":"Confundir finalidade disciplinar com autorização para degradar.","review":"Arts. 17–18-A"},{"id":"EC03","kind":"Questão autoral","difficulty":"Difícil","topic":"Art. 245","stem":"Sobre a omissão de comunicação de maus-tratos, assinale a correta.","options":["O art. 245 não menciona professor.","A infração alcança médico, professor ou responsável por estabelecimentos indicados, incluindo pré-escola e creche.","Somente o diretor pode responder.","A multa não é agravada em reincidência."],"answer":1,"explanation":"O art. 245 menciona professor e pré-escola/creche e prevê multa dobrada na reincidência.","trap":"Confundir art. 56, mais restrito ao dirigente do ensino fundamental, com art. 245.","review":"Art. 245"},{"id":"EC04","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 53","stem":"O responsável de uma criança pede informações sobre o processo pedagógico. A escola afirma que o ECA não assegura participação familiar. Essa resposta está:","options":["Correta, pois o currículo é sigiloso.","Incorreta, pois o art. 53 assegura ciência do processo pedagógico e participação na definição das propostas educacionais.","Correta apenas na pré-escola.","Incorreta apenas se houver ordem judicial."],"answer":1,"explanation":"O parágrafo único do art. 53 prevê expressamente esses direitos dos pais ou responsáveis.","trap":"Confundir participação com poder individual de veto sobre toda decisão escolar.","review":"Art. 53"},{"id":"EC05","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 53","stem":"A garantia de vaga para irmãos no mesmo estabelecimento aplica-se quando:","options":["Frequentarem necessariamente a mesma turma.","Frequentarem a mesma etapa ou ciclo de ensino da educação básica, observada a regra legal.","Tiverem qualquer diferença de idade.","A família possuir renda inferior a um salário mínimo."],"answer":1,"explanation":"A redação do art. 53 vincula a garantia a irmãos que frequentem a mesma etapa ou ciclo.","trap":"Trocar etapa/ciclo por turma/série idêntica.","review":"Art. 53"},{"id":"EC06","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 136","stem":"Assinale uma atribuição do Conselho Tutelar.","options":["Proferir sentença penal contra agressor.","Requisitar serviços públicos em áreas como saúde, educação e assistência social.","Condenar pais à prisão civil diretamente.","Anular matrícula escolar por decisão administrativa própria."],"answer":1,"explanation":"O art. 136 permite requisitar serviços públicos; CT não é órgão jurisdicional.","trap":"Dar ao CT poderes típicos do Judiciário.","review":"Art. 136"},{"id":"EC07","kind":"Questão autoral","difficulty":"Médio","topic":"Arts. 103–105","stem":"Uma criança de 11 anos pratica conduta descrita como crime. Segundo a lógica do ECA:","options":["É penalmente responsabilizada como adulto.","Correspondem-lhe as medidas de proteção previstas no art. 101.","Recebe obrigatoriamente internação socioeducativa.","O fato é juridicamente inexistente."],"answer":1,"explanation":"O art. 105 remete o ato infracional praticado por criança às medidas do art. 101.","trap":"Aplicar automaticamente ao menor de 12 o regime socioeducativo do adolescente.","review":"Arts. 103–105"},{"id":"EC08","kind":"Questão autoral","difficulty":"Médio","topic":"Atualização 2025","stem":"Qual conjunto corresponde à redação atualizada dos deveres parentais do art. 22?","options":["Sustento e guarda apenas.","Sustento, guarda, convivência, assistência material e afetiva e educação.","Somente educação e alimentação.","Guarda, disciplina física e escolarização."],"answer":1,"explanation":"A Lei 15.240/2025 ampliou expressamente a redação do art. 22.","trap":"Estudar material antigo e ignorar convivência/assistência afetiva.","review":"Art. 22 atualizado"},{"id":"EC09","kind":"Questão autoral","difficulty":"Médio","topic":"Atualização 2025","stem":"Desde 2025, o art. 56 acrescentou à lista de situações comunicáveis ao Conselho Tutelar:","options":["Qualquer nota abaixo da média.","Negligência, abuso ou abandono na forma dos arts. 4º e 5º.","Toda discussão entre colegas.","Atraso escolar de um único dia."],"answer":1,"explanation":"Foi incluído o inciso IV com negligência, abuso ou abandono.","trap":"Confundir problema pedagógico corriqueiro com hipótese legal.","review":"Art. 56 atualizado"},{"id":"EC10","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 19","stem":"Uma criança está em acolhimento institucional há 18 meses. A continuidade:","options":["É automaticamente proibida em qualquer hipótese.","Só pode ultrapassar a regra de 18 meses se houver comprovada necessidade que atenda ao superior interesse, devidamente fundamentada pela autoridade judiciária.","Pode durar indefinidamente por decisão administrativa da instituição.","Depende apenas da vontade da família acolhedora."],"answer":1,"explanation":"O prazo de 18 meses admite exceção fundamentada no superior interesse.","trap":"Tratar o prazo como absoluto ou inexistente.","review":"Art. 19"},{"id":"EC11","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 98","stem":"Qual situação NÃO é uma das três hipóteses gerais do art. 98?","options":["Ação ou omissão da sociedade ou do Estado.","Falta, omissão ou abuso dos pais ou responsável.","Razão da própria conduta da criança/adolescente.","Desempenho escolar abaixo da média, por si só."],"answer":3,"explanation":"Baixo desempenho isolado não integra a estrutura do art. 98.","trap":"Introduzir um problema escolar plausível como se fosse hipótese legal.","review":"Art. 98"},{"id":"EC12","kind":"Questão autoral","difficulty":"Difícil","topic":"Art. 131 × 137","stem":"Assinale a sequência correta: I. CT é não jurisdicional. II. Suas decisões podem ser revistas judicialmente. III. Por ser autônomo, suas decisões nunca são revisáveis.","options":["V – V – F.","V – F – V.","F – V – F.","F – F – V."],"answer":0,"explanation":"Autonomia não significa irrevisibilidade. O art. 137 prevê revisão pela autoridade judiciária.","trap":"Interpretar autonomia como ausência de controle judicial.","review":"Arts. 131 e 137"},{"id":"EC13","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 59-A","stem":"Sobre antecedentes de colaboradores em instituições que atuam com crianças e adolescentes, assinale a correta.","options":["O ECA não trata do tema.","O art. 59-A, incluído em 2024, criou deveres de manutenção de certidões/fichas em instituições abrangidas pela norma.","Só se aplica a clubes esportivos profissionais.","Substitui todas as demais medidas de proteção escolar."],"answer":1,"explanation":"O art. 59-A é recente e trata de antecedentes/fichas cadastrais conforme o tipo de instituição.","trap":"Generalizar ou restringir indevidamente a inovação.","review":"Art. 59-A"},{"id":"EC14","kind":"Questão autoral","difficulty":"Médio","topic":"Art. 4º atualizado","stem":"A assistência afetiva prevista no ECA após alteração de 2025:","options":["É irrelevante juridicamente.","Integra dever parental e envolve acompanhamento afetivo da formação da pessoa em desenvolvimento.","É sinônimo de pagamento de pensão alimentícia apenas.","Só existe durante a primeira infância."],"answer":1,"explanation":"O art. 4º passou a explicitar assistência afetiva e detalhar exemplos; o art. 5º menciona abandono afetivo.","trap":"Reduzir assistência afetiva a recurso material.","review":"Arts. 4º–5º atualizados"},{"id":"EC15","kind":"Questão autoral","difficulty":"Difícil","topic":"Art. 56 × 245","stem":"Qual comparação está correta?","options":["Art. 56 e art. 245 possuem exatamente os mesmos sujeitos e hipóteses.","Art. 56 disciplina comunicações por dirigentes do ensino fundamental; art. 245 tipifica omissão envolvendo também professor e menciona pré-escola e creche.","Art. 245 só vale para hospitais.","Art. 56 aplica multa de 3 a 20 salários ao professor."],"answer":1,"explanation":"A diferença de sujeito e alcance é ponto de alta relevância para Educador Infantil.","trap":"Fundir dois artigos próximos em uma única regra.","review":"Art. 56 × art. 245"}],"ecamock":[{"id":"EM01","kind":"Simulado Rank 3","difficulty":"Fácil","topic":"Art. 1º","stem":"O princípio estruturante enunciado no art. 1º do ECA é a:","options":["Proteção integral.","Tutela penal integral.","Escolarização compulsória integral.","Autonomia familiar absoluta."],"answer":0,"explanation":"O art. 1º dispõe sobre proteção integral.","trap":"Trocar o princípio por expressões plausíveis.","review":"Art. 1º"},{"id":"EM02","kind":"Simulado Rank 3","difficulty":"Fácil","topic":"Art. 2º","stem":"Uma pessoa com 11 anos e 11 meses é, para o ECA:","options":["Adolescente.","Criança.","Jovem adulta.","A classificação depende da escolaridade."],"answer":1,"explanation":"Até 12 anos incompletos = criança.","trap":"Ignorar a palavra incompletos.","review":"Art. 2º"},{"id":"EM03","kind":"Simulado Rank 3","difficulty":"Médio","topic":"Art. 4º","stem":"Qual termo NÃO pertence ao núcleo legal da garantia de prioridade?","options":["Primazia.","Precedência.","Preferência.","Exclusividade universal."],"answer":3,"explanation":"A lei fala também em destinação privilegiada de recursos, não em exclusividade universal.","trap":"Absoluta prioridade ≠ exclusividade absoluta.","review":"Art. 4º"},{"id":"EM04","kind":"Simulado Rank 3","difficulty":"Médio","topic":"Art. 13","stem":"A escola suspeita de maus-tratos. Segundo o ECA:","options":["Deve aguardar confirmação.","A suspeita já é contemplada no dever de comunicação ao Conselho Tutelar.","Só a família pode comunicar.","A comunicação é facultativa ao professor."],"answer":1,"explanation":"Suspeita ou confirmação estão expressamente no art. 13.","trap":"Exigir certeza.","review":"Art. 13"},{"id":"EM05","kind":"Simulado Rank 3","difficulty":"Médio","topic":"Art. 18-A","stem":"Qual situação corresponde melhor a tratamento cruel/degradante?","options":["Orientar com firmeza e respeito.","Ridicularizar a criança diante do grupo como forma de disciplina.","Organizar rotina visual.","Retirar temporariamente um material perigoso."],"answer":1,"explanation":"Ridicularização está expressamente na definição.","trap":"Confundir limite pedagógico com degradação.","review":"Art. 18-A"},{"id":"EM06","kind":"Simulado Rank 3","difficulty":"Médio","topic":"Art. 19","stem":"A situação de criança/adolescente acolhido deve ser reavaliada, no máximo, a cada:","options":["30 dias.","3 meses.","6 meses.","12 meses."],"answer":1,"explanation":"O prazo vigente é 3 meses.","trap":"Usar antiga redação de 6 meses.","review":"Art. 19"},{"id":"EM07","kind":"Simulado Rank 3","difficulty":"Médio","topic":"Art. 19","stem":"A permanência em acolhimento institucional, como regra, não se prolongará por mais de:","options":["6 meses.","12 meses.","18 meses.","24 meses."],"answer":2,"explanation":"A regra é 18 meses, ressalvada necessidade superior fundamentada.","trap":"Memorizar redação histórica de 2 anos.","review":"Art. 19"},{"id":"EM08","kind":"Simulado Rank 3","difficulty":"Fácil","topic":"Art. 23","stem":"A carência material da família:","options":["Autoriza automaticamente perda do poder familiar.","Não é motivo suficiente, isoladamente, para perda ou suspensão.","Impõe adoção imediata.","Dispensa políticas públicas de apoio."],"answer":1,"explanation":"Art. 23.","trap":"Pobreza ≠ perda automática.","review":"Art. 23"},{"id":"EM09","kind":"Simulado Rank 3","difficulty":"Médio","topic":"Art. 53","stem":"Assinale a alternativa INCORRETA.","options":["O estudante tem direito de ser respeitado por seus educadores.","Pode contestar critérios avaliativos e recorrer a instâncias escolares superiores.","Pais/responsáveis podem ter ciência do processo pedagógico.","O ECA proíbe qualquer participação dos pais na definição das propostas educacionais."],"answer":3,"explanation":"O parágrafo único assegura participação.","trap":"Inverter direito em proibição.","review":"Art. 53"},{"id":"EM10","kind":"Simulado Rank 3","difficulty":"Fácil","topic":"Art. 54","stem":"Creche e pré-escola, segundo o art. 54, alcançam crianças:","options":["De zero a cinco anos.","De zero a seis anos completos.","Apenas de quatro e cinco.","Apenas até três."],"answer":0,"explanation":"Redação atual: zero a cinco anos.","trap":"Usar redação antiga.","review":"Art. 54"},{"id":"EM11","kind":"Simulado Rank 3","difficulty":"Médio","topic":"Art. 56","stem":"Qual é um caso previsto no art. 56?","options":["Indisciplina isolada.","Reiteração de faltas injustificadas e evasão, esgotados os recursos escolares.","Discordância entre professor e família sobre atividade.","Ausência em um único dia."],"answer":1,"explanation":"É uma das hipóteses expressas.","trap":"Transformar qualquer problema escolar em comunicação obrigatória.","review":"Art. 56"},{"id":"EM12","kind":"Simulado Rank 3","difficulty":"Médio","topic":"Art. 98","stem":"Direitos ameaçados por omissão do Estado podem ensejar:","options":["Medidas de proteção.","Somente processo penal contra a criança.","Perda automática do poder familiar.","Nenhuma atuação do ECA."],"answer":0,"explanation":"Ação ou omissão da sociedade ou do Estado é hipótese do art. 98.","trap":"Focar apenas nos pais como possíveis agentes de violação.","review":"Art. 98"},{"id":"EM13","kind":"Simulado Rank 3","difficulty":"Médio","topic":"Art. 99","stem":"As medidas de proteção:","options":["Só podem ser aplicadas uma de cada vez e jamais substituídas.","Podem ser isoladas ou cumulativas e substituídas a qualquer tempo.","Exigem sempre internação.","São penas criminais."],"answer":1,"explanation":"Art. 99.","trap":"Confundir proteção com punição.","review":"Art. 99"},{"id":"EM14","kind":"Simulado Rank 3","difficulty":"Fácil","topic":"Art. 131","stem":"O Conselho Tutelar é não jurisdicional. Isso significa que:","options":["Não integra função judicial e não profere decisões jurisdicionais como um juiz.","Não pode tomar nenhuma decisão administrativa.","É subordinado ao diretor escolar.","É uma vara especializada do Judiciário."],"answer":0,"explanation":"CT possui atribuições próprias, mas não é órgão jurisdicional.","trap":"Interpretar “não jurisdicional” como “sem poder de atuação”.","review":"Art. 131"},{"id":"EM15","kind":"Simulado Rank 3","difficulty":"Médio","topic":"Art. 132","stem":"O Conselho Tutelar possui:","options":["5 membros e mandato de 4 anos.","4 membros e mandato de 5 anos.","3 membros e mandato de 3 anos.","7 membros e mandato vitalício."],"answer":0,"explanation":"Regra atual do art. 132.","trap":"Usar números de redações antigas.","review":"Art. 132"},{"id":"EM16","kind":"Simulado Rank 3","difficulty":"Médio","topic":"Art. 133","stem":"Não é requisito nacional básico de candidatura a conselheiro tutelar:","options":["Reconhecida idoneidade moral.","Idade superior a 21 anos.","Residir no município.","Ser bacharel em Direito."],"answer":3,"explanation":"A lei não exige graduação em Direito.","trap":"Adicionar requisito profissional não previsto no art. 133.","review":"Art. 133"},{"id":"EM17","kind":"Simulado Rank 3","difficulty":"Médio","topic":"Art. 136","stem":"O Conselho Tutelar pode:","options":["Requisitar serviços públicos em áreas previstas no ECA.","Condenar criminalmente um agressor.","Decretar adoção por conta própria.","Substituir definitivamente o Poder Judiciário."],"answer":0,"explanation":"Requisição de serviços é atribuição expressa.","trap":"Dar ao CT poder jurisdicional.","review":"Art. 136"},{"id":"EM18","kind":"Simulado Rank 3","difficulty":"Fácil","topic":"Art. 137","stem":"Quem pode rever decisão do Conselho Tutelar nos termos do ECA?","options":["Autoridade judiciária, a pedido de legítimo interessado.","Diretor escolar, de ofício.","Conselho de classe.","Secretário municipal de educação, automaticamente."],"answer":0,"explanation":"Art. 137.","trap":"Misturar órgãos da rede de proteção.","review":"Art. 137"},{"id":"EM19","kind":"Simulado Rank 3","difficulty":"Difícil","topic":"Art. 245","stem":"Um professor de pré-escola toma conhecimento de suspeita de maus-tratos e, sem justificativa, deixa de comunicar à autoridade competente. O ECA:","options":["Não prevê consequência porque art. 245 só trata de médicos.","Prevê infração administrativa, com multa, alcançando professor e pré-escola/creche.","Prevê apenas advertência pedagógica da escola.","Só se aplica se houver sentença criminal anterior."],"answer":1,"explanation":"O art. 245 é diretamente relevante à Educação Infantil.","trap":"Esquecer que pré-escola e creche aparecem expressamente.","review":"Art. 245"},{"id":"EM20","kind":"Simulado Rank 3","difficulty":"Difícil","topic":"Síntese","stem":"Qual sequência está correta? I. Pobreza isolada não basta para perda do poder familiar. II. CT é órgão não jurisdicional. III. Suspeita de maus-tratos não precisa ser comunicada até confirmação.","options":["V – V – F.","V – F – V.","F – V – F.","F – F – V."],"answer":0,"explanation":"I corresponde ao art. 23; II ao art. 131; III contraria o art. 13.","trap":"Misturar três núcleos de alta incidência.","review":"Revisão geral ECA"}],"r4adapted":[{"id":"R4A01","kind":"Questão adaptada","difficulty":"Fácil","topic":"Associação de autores","stem":"Em uma questão de associação, qual trio está corretamente relacionado?","options":["Vygotsky—mediação; Piaget—epistemologia genética; Wallon—afetividade.","Vygotsky—epistemologia genética; Piaget—afetividade; Wallon—mediação.","Vygotsky—comportamentalismo; Piaget—mediação; Wallon—educação bancária.","Vygotsky—afetividade; Piaget—behaviorismo; Wallon—ZDP."],"answer":0,"explanation":"É exatamente o padrão de associação confirmado na prova UniFil de Jardim Alegre/2019.","trap":"A banca troca palavras-chave verdadeiras entre autores.","review":"Autor × conceito"},{"id":"R4A02","kind":"Questão adaptada","difficulty":"Fácil","topic":"Piaget — estágios","stem":"Assinale a sequência correta dos estágios de desenvolvimento cognitivo em Piaget.","options":["Pré-operatório → sensório-motor → concreto → formal.","Sensório-motor → pré-operatório → operações concretas → operações formais.","Sensório-motor → concreto → pré-operatório → formal.","Pré-operatório → concreto → sensório-motor → formal."],"answer":1,"explanation":"A ordem clássica é sensório-motor, pré-operatório, operações concretas e operações formais.","trap":"Troca simples de ordem, usada pela UniFil.","review":"Piaget — estágios"},{"id":"R4A03","kind":"Questão adaptada","difficulty":"Médio","topic":"Piaget — identificação","stem":"Uma criança já realiza operações lógicas aplicadas a situações concretas, compreende conservação e reversibilidade. Segundo Piaget, está no estágio:","options":["sensório-motor.","pré-operatório.","operações concretas.","operações formais."],"answer":2,"explanation":"Conservação, reversibilidade, classificação e seriação caracterizam as operações concretas.","trap":"“Operação lógica” pode induzir à escolha do formal.","review":"Piaget — operações concretas"},{"id":"R4A04","kind":"Questão adaptada","difficulty":"Fácil","topic":"Vygotsky — ZDP","stem":"Na perspectiva de Vygotsky, a Zona de Desenvolvimento Proximal relaciona-se à diferença entre:","options":["o que a criança memoriza e o que esquece.","o que faz sozinha e o que consegue realizar com orientação ou colaboração adequada.","o que aprende em casa e o que aprende na escola.","o desenvolvimento biológico e a idade cronológica."],"answer":1,"explanation":"A formulação corresponde ao núcleo clássico da ZDP e ao que a UniFil já cobrou.","trap":"Transformar ZDP em diferença entre ambientes ou idades.","review":"Vygotsky — ZDP"},{"id":"R4A05","kind":"Questão adaptada","difficulty":"Médio","topic":"Vygotsky — conceitos","stem":"Relacione mentalmente: mediação, linguagem, cultura e internalização. Assinale a alternativa correta.","options":["Cultura é um sistema histórico de significados; linguagem medeia comunicação e pensamento; internalização envolve transformação de processos sociais em processos psicológicos do indivíduo.","Cultura é biológica; linguagem é apenas expressão; internalização é cópia.","Mediação torna o professor dispensável; linguagem surge sem interação social.","Internalização é sinônimo de memorização mecânica e cultura não interfere no desenvolvimento."],"answer":0,"explanation":"Os conceitos formam um sistema histórico-cultural articulado.","trap":"A UniFil já cobrou associação desses quatro termos.","review":"Vygotsky — linguagem e cultura"},{"id":"R4A06","kind":"Questão adaptada","difficulty":"Médio","topic":"Vygotsky — desenvolvimento","stem":"Assinale a alternativa mais coerente com Vygotsky.","options":["O bom ensino limita-se ao que a criança já domina sozinha.","A aprendizagem escolar só deve ocorrer após a maturação completa.","O ensino pode mobilizar funções psicológicas em vias de desenvolvimento.","Interações sociais têm importância apenas afetiva, não cognitiva."],"answer":2,"explanation":"Na perspectiva histórico-cultural, o ensino bem organizado pode atuar sobre processos em desenvolvimento.","trap":"Confundir desenvolvimento real com limite do ensino.","review":"Vygotsky — aprendizagem e desenvolvimento"},{"id":"R4A07","kind":"Questão adaptada","difficulty":"Médio","topic":"Piaget — assimilação","stem":"Uma criança que conhece apenas cães vê uma raposa e inicialmente a chama de “cachorro”. O processo predominante é:","options":["acomodação.","assimilação.","internalização.","mediação."],"answer":1,"explanation":"Ela tenta compreender o novo por um esquema já existente.","trap":"Inverter assimilação e acomodação.","review":"Piaget — assimilação"},{"id":"R4A08","kind":"Questão adaptada","difficulty":"Médio","topic":"Piaget — acomodação","stem":"Depois de observar diferenças entre cão e raposa, a criança modifica sua categoria e passa a distingui-los. O processo predominante é:","options":["acomodação.","assimilação.","centração.","internalização."],"answer":0,"explanation":"Acomodação envolve modificação/reorganização de esquemas diante de novas exigências.","trap":"A banca pode repetir o mesmo exemplo para inverter os termos.","review":"Piaget — acomodação"},{"id":"R4A09","kind":"Questão adaptada","difficulty":"Médio","topic":"Piaget — pré-operatório","stem":"É característica típica do período pré-operatório:","options":["raciocínio hipotético-dedutivo sistemático.","domínio consolidado da conservação.","função simbólica e pensamento intuitivo, com centramento e egocentrismo cognitivo.","ausência de representação e linguagem."],"answer":2,"explanation":"O pré-operatório é marcado por representação simbólica, mas ainda sem operações lógicas reversíveis consolidadas.","trap":"Confundir simbolização com operações formais.","review":"Piaget — pré-operatório"},{"id":"R4A10","kind":"Questão adaptada","difficulty":"Fácil","topic":"Wallon — conceito","stem":"Na associação clássica usada pela UniFil, Wallon aparece ligado principalmente a:","options":["afetividade.","epistemologia genética.","reforço operante.","zona de desenvolvimento proximal."],"answer":0,"explanation":"A prova UniFil de Jardim Alegre/2019 relacionou diretamente Wallon à afetividade.","trap":"Palavras-chave de outros autores.","review":"Wallon — afetividade"},{"id":"R4A11","kind":"Questão adaptada","difficulty":"Médio","topic":"Wallon — integração","stem":"Assinale a alternativa correta sobre Wallon.","options":["O desenvolvimento é explicado apenas pela emoção.","Afetividade, movimento e cognição são dimensões integradas na constituição da pessoa.","A motricidade perde qualquer função psicológica após o nascimento.","O meio social tem papel irrelevante diante da maturação biológica."],"answer":1,"explanation":"Wallon propõe uma visão integrada da pessoa e da relação organismo–meio.","trap":"Reduzir Wallon a “emoção”.","review":"Wallon — integração funcional"},{"id":"R4A12","kind":"Questão adaptada","difficulty":"Médio","topic":"Wallon — estágios","stem":"A fase aproximadamente entre 3 e 6 anos, marcada por afirmação do eu, oposição, sedução e imitação, é denominada por Wallon:","options":["categorial.","personalismo.","impulsivo-emocional.","operações concretas."],"answer":1,"explanation":"O personalismo ocupa centralmente a construção do eu e as relações interpessoais.","trap":"Misturar estágio de Wallon com estágio de Piaget.","review":"Wallon — personalismo"},{"id":"R4A13","kind":"Questão adaptada","difficulty":"Difícil","topic":"Comparação","stem":"Assinale a alternativa incorreta.","options":["Piaget destaca mecanismos de assimilação e acomodação.","Vygotsky atribui papel central à mediação cultural e à linguagem.","Wallon articula afetividade, movimento e cognição.","Vygotsky organiza o desenvolvimento em quatro estágios universais idênticos aos de Piaget."],"answer":3,"explanation":"A sequência de quatro estágios é característica da teoria piagetiana, não de Vygotsky.","trap":"A banca pode transplantar estruturas de uma teoria para outra.","review":"Comparação dos autores"},{"id":"R4A14","kind":"Questão adaptada","difficulty":"Difícil","topic":"Vygotsky — internalização","stem":"Quando uma forma de regulação inicialmente construída na interação social passa a integrar o funcionamento psicológico da criança, trata-se principalmente de:","options":["conservação.","internalização.","equilibração.","personalismo."],"answer":1,"explanation":"Internalização descreve a transformação/reconstrução de processos inicialmente sociais em funcionamento individual.","trap":"Palavras verdadeiras, mas de outras teorias.","review":"Vygotsky — internalização"},{"id":"R4A15","kind":"Questão adaptada","difficulty":"Médio","topic":"Piaget — egocentrismo","stem":"No pensamento pré-operatório, “egocentrismo” significa principalmente:","options":["egoísmo moral e recusa em compartilhar.","dificuldade de coordenar plenamente o próprio ponto de vista com perspectivas diferentes.","ausência de vínculos afetivos.","incapacidade de brincar simbolicamente."],"answer":1,"explanation":"Egocentrismo é um conceito cognitivo ligado à perspectiva, não sinônimo de egoísmo.","trap":"Explorar o sentido cotidiano da palavra.","review":"Piaget — egocentrismo"}],"r4authorial":[{"id":"R4B01","kind":"Questão autoral","difficulty":"Médio","topic":"Vygotsky — mediação","stem":"Uma educadora oferece pistas, reorganiza materiais e convida uma criança mais experiente para cooperar. A interpretação mais adequada é:","options":["a mediação pode ocorrer por pessoas, signos e organização de instrumentos/condições.","a professora retirou autonomia e impediu aprendizagem.","a aprendizagem só é válida quando totalmente independente.","a ajuda transforma o desempenho assistido automaticamente em nível real."],"answer":0,"explanation":"Mediação é mais ampla que “explicar verbalmente”; inclui signos, instrumentos e relações.","trap":"Confundir autonomia com ausência de apoio.","review":"Vygotsky — mediação"},{"id":"R4B02","kind":"Questão autoral","difficulty":"Difícil","topic":"Vygotsky — ZDP","stem":"Qual afirmação é mais precisa sobre ZDP?","options":["É um conteúdo curricular fixo próprio de cada idade.","É uma propriedade que pode ser medida apenas por testes individuais.","Refere-se a processos em desenvolvimento evidenciados na relação entre atividade independente e colaboração orientada.","É sinônimo de nível potencial e elimina o nível real."],"answer":2,"explanation":"A ZDP é relacional e dinâmica, não uma lista fixa nem um terceiro “nível” independente.","trap":"Tratar ZDP como pacote de conteúdos.","review":"Vygotsky — ZDP"},{"id":"R4B03","kind":"Questão autoral","difficulty":"Difícil","topic":"Vygotsky — aprendizagem","stem":"Assinale a alternativa que evita uma simplificação comum.","options":["Qualquer interação social produz necessariamente desenvolvimento.","Ensino e desenvolvimento são idênticos e acontecem no mesmo ritmo.","O ensino pode criar condições para processos de desenvolvimento, mas não os produz de forma mecânica.","A aprendizagem é irrelevante para o desenvolvimento psicológico."],"answer":2,"explanation":"A relação é constitutiva, mas não mecânica; uma prática pedagógica inadequada não garante desenvolvimento.","trap":"Transformar mediação em causalidade automática.","review":"Vygotsky — ensino e desenvolvimento"},{"id":"R4B04","kind":"Questão autoral","difficulty":"Médio","topic":"Piaget — equilibração","stem":"Quando uma informação entra em conflito com um esquema e a criança reorganiza sua compreensão para alcançar uma estrutura mais estável, o processo regulador é:","options":["equilibração.","internalização.","imitação diferida.","alternância funcional."],"answer":0,"explanation":"Equilibração regula a dinâmica entre assimilação e acomodação e novas organizações cognitivas.","trap":"Confundir processos de teorias diferentes.","review":"Piaget — equilibração"},{"id":"R4B05","kind":"Questão autoral","difficulty":"Médio","topic":"Piaget — conservação","stem":"A mesma quantidade de líquido é transferida de um copo baixo e largo para outro alto e estreito. A criança afirma que “agora tem mais”. Essa resposta é compatível com:","options":["conservação consolidada.","centração em um aspecto perceptivo e dificuldade de reversibilidade.","raciocínio formal.","internalização de signos."],"answer":1,"explanation":"No pré-operatório, a criança pode centrar-se na altura e não coordenar simultaneamente as dimensões.","trap":"Confundir percepção dominante com falta de inteligência.","review":"Piaget — conservação"},{"id":"R4B06","kind":"Questão autoral","difficulty":"Médio","topic":"Piaget — professor","stem":"Qual prática é mais compatível com uma leitura construtivista de Piaget?","options":["Fornecer respostas prontas para evitar desequilíbrio.","Organizar desafios, comparação, manipulação, argumentação e reconstrução das hipóteses.","Deixar a criança sempre sozinha porque ensinar atrapalha a construção.","Exigir memorização antes de qualquer ação."],"answer":1,"explanation":"O professor cria condições para ação e reorganização cognitiva; não é transmissor exclusivo nem ausente.","trap":"Espontaneísmo vendido como construtivismo.","review":"Piaget — papel do professor"},{"id":"R4B07","kind":"Questão autoral","difficulty":"Médio","topic":"Wallon — afetividade","stem":"Uma criança reage corporalmente a uma situação frustrante antes de conseguir explicá-la verbalmente. A leitura walloniana enfatiza:","options":["separação entre corpo e psiquismo.","função expressiva da emoção e integração entre afetividade e movimento.","que emoção não tem função social.","que apenas a cognição explica o comportamento."],"answer":1,"explanation":"Em Wallon, emoção e movimento têm forte função expressiva e relacional.","trap":"Reduzir comportamento corporal a “mau comportamento”.","review":"Wallon — emoção e movimento"},{"id":"R4B08","kind":"Questão autoral","difficulty":"Médio","topic":"Wallon — meio","stem":"Para Wallon, considerar o meio significa:","options":["adotar determinismo ambiental absoluto.","entender desenvolvimento na relação dialética entre organismo, relações sociais e condições do meio.","ignorar condições orgânicas.","tratar escola apenas como espaço físico."],"answer":1,"explanation":"O meio participa do desenvolvimento sem ser um determinante mecânico isolado.","trap":"Trocar relação dialética por determinismo.","review":"Wallon — organismo e meio"},{"id":"R4B09","kind":"Questão autoral","difficulty":"Difícil","topic":"Wallon — alternância","stem":"A alternância funcional em Wallon significa que:","options":["afetividade e cognição se revezam de modo que uma desaparece completamente.","há mudanças de predominância entre orientações afetivas e cognitivas, mantendo integração entre funções.","os estágios não possuem qualquer continuidade.","o desenvolvimento repete sempre a mesma etapa."],"answer":1,"explanation":"Predominância não equivale a exclusão; os conjuntos funcionais permanecem integrados.","trap":"Interpretar alternância como “liga/desliga”.","review":"Wallon — alternância funcional"},{"id":"R4B10","kind":"Questão autoral","difficulty":"Difícil","topic":"Comparação","stem":"Uma questão descreve “conflito cognitivo causado por informação que não cabe no esquema atual”. O autor/conjunto conceitual mais direto é:","options":["Vygotsky — ZDP e mediação.","Piaget — assimilação, acomodação e equilibração.","Wallon — personalismo e alternância.","Skinner — reforço e punição."],"answer":1,"explanation":"A dinâmica de esquemas e reequilibração é piagetiana.","trap":"Todas as teorias lidam com mudança, mas os termos são específicos.","review":"Comparação dos autores"},{"id":"R4B11","kind":"Questão autoral","difficulty":"Difícil","topic":"Comparação","stem":"Uma questão descreve “função que surge primeiro entre pessoas e depois é reconstruída no plano individual”. O autor mais diretamente associado é:","options":["Piaget.","Wallon.","Vygotsky.","Montessori."],"answer":2,"explanation":"A relação interpsicológico → intrapsicológico é característica da teoria histórico-cultural.","trap":"Confundir construção ativa com internalização.","review":"Vygotsky — social e individual"},{"id":"R4B12","kind":"Questão autoral","difficulty":"Difícil","topic":"Comparação","stem":"Uma questão descreve “movimento, emoção e inteligência como conjuntos funcionais integrados”. O autor é:","options":["Wallon.","Piaget.","Vygotsky.","Freire."],"answer":0,"explanation":"É marca central da psicogenética walloniana.","trap":"A palavra “inteligência” pode levar indevidamente a Piaget.","review":"Wallon — campos funcionais"},{"id":"R4B13","kind":"Questão autoral","difficulty":"Difícil","topic":"Educação Infantil","stem":"No faz de conta, uma criança usa um bloco como telefone e assume o papel de médica. A leitura mais adequada é:","options":["Para Piaget, evidencia função simbólica; para Vygotsky, a situação imaginária também pode envolver significados e regras sociais.","Somente Wallon permite explicar brincadeira simbólica.","A situação comprova operações formais.","Não há aprendizagem porque o objeto não é um telefone real."],"answer":0,"explanation":"Uma mesma situação pode ser analisada por teorias distintas; a pergunta de prova deve indicar o conceito solicitado.","trap":"Forçar exclusividade quando há leituras diferentes.","review":"Comparação em situação prática"},{"id":"R4B14","kind":"Questão autoral","difficulty":"Médio","topic":"Piaget × Wallon","stem":"Qual alternativa diferencia corretamente o personalismo de Wallon do egocentrismo piagetiano?","options":["São sinônimos exatos.","Personalismo refere-se à construção/afirmação da pessoa nas relações; egocentrismo é dificuldade cognitiva de coordenar perspectivas.","Egocentrismo é estágio de Wallon; personalismo é estágio de Piaget.","Ambos significam egoísmo moral."],"answer":1,"explanation":"São conceitos distintos, de teorias distintas.","trap":"A semelhança superficial pode causar troca.","review":"Piaget × Wallon"},{"id":"R4B15","kind":"Questão autoral","difficulty":"Difícil","topic":"Teoria e prática","stem":"Uma educadora observa que uma criança ainda não resolve uma classificação sozinha. Qual conduta é conceitualmente mais defensável?","options":["Concluir que não deve propor nenhuma experiência relacionada até que a maturação ocorra.","Oferecer apoio graduado e problemas significativos, observando como a criança pensa e ajustando a intervenção.","Fornecer diretamente a resposta correta e exigir cópia.","Aplicar punição por não dominar a classificação."],"answer":1,"explanation":"A prática dialoga com mediação vygotskiana e atividade construtiva piagetiana sem misturar os conceitos como se fossem idênticos.","trap":"Questões podem exigir prática coerente, não fidelidade a uma única etiqueta.","review":"Aplicação pedagógica"}],"r4mock":[{"id":"R4M01","kind":"Simulado","difficulty":"Fácil","topic":"Autores","stem":"Mediação, Epistemologia Genética e Afetividade correspondem, respectivamente, a:","options":["Piaget, Wallon, Vygotsky.","Vygotsky, Piaget, Wallon.","Wallon, Vygotsky, Piaget.","Vygotsky, Wallon, Piaget."],"answer":1,"explanation":"É a associação confirmada em prova UniFil.","trap":"Troca de conceitos.","review":"Autor × conceito"},{"id":"R4M02","kind":"Simulado","difficulty":"Médio","topic":"Vygotsky","stem":"O nível de desenvolvimento real é melhor representado por:","options":["o que a criança realiza de forma independente.","qualquer tarefa que só realiza com ajuda.","a idade cronológica.","o currículo previsto para sua turma."],"answer":0,"explanation":"Real/atual = desempenho independente já consolidado.","trap":"Confundir real e potencial.","review":"Vygotsky — ZDP"},{"id":"R4M03","kind":"Simulado","difficulty":"Médio","topic":"Vygotsky","stem":"Na teoria histórico-cultural, linguagem é:","options":["apenas meio de transmitir pensamentos prontos.","sistema simbólico central na comunicação, pensamento e autorregulação.","um reflexo biológico sem papel cultural.","irrelevante antes da alfabetização."],"answer":1,"explanation":"Linguagem é forma de mediação simbólica central.","trap":"Reduzir linguagem à fala escolar.","review":"Vygotsky — linguagem"},{"id":"R4M04","kind":"Simulado","difficulty":"Médio","topic":"Vygotsky","stem":"Internalização é:","options":["cópia automática do adulto.","reconstrução no plano individual de processos constituídos socialmente.","mudança de estágio em Piaget.","fase de Wallon."],"answer":1,"explanation":"O processo envolve transformação, não cópia mecânica.","trap":"Confundir teorias.","review":"Vygotsky — internalização"},{"id":"R4M05","kind":"Simulado","difficulty":"Fácil","topic":"Piaget","stem":"Qual é o primeiro estágio piagetiano?","options":["Pré-operatório.","Sensório-motor.","Operações concretas.","Operações formais."],"answer":1,"explanation":"A sequência começa pelo sensório-motor.","trap":"Ordem.","review":"Piaget — estágios"},{"id":"R4M06","kind":"Simulado","difficulty":"Médio","topic":"Piaget","stem":"Função simbólica, faz de conta e dificuldade de conservação apontam para:","options":["sensório-motor.","pré-operatório.","operações concretas.","operações formais."],"answer":1,"explanation":"São marcas clássicas do pré-operatório.","trap":"Faz de conta pode levar a Vygotsky, mas o conjunto de pistas é piagetiano.","review":"Piaget — pré-operatório"},{"id":"R4M07","kind":"Simulado","difficulty":"Médio","topic":"Piaget","stem":"Conservação e reversibilidade são mais típicas de:","options":["operações concretas.","pré-operatório.","sensório-motor.","impulsivo-emocional."],"answer":0,"explanation":"São aquisições centrais das operações concretas.","trap":"Misturar estágio de Wallon.","review":"Piaget — concreto"},{"id":"R4M08","kind":"Simulado","difficulty":"Médio","topic":"Piaget","stem":"Inserir nova informação em um esquema existente é:","options":["acomodação.","assimilação.","mediação.","internalização."],"answer":1,"explanation":"Assimilação incorpora o novo ao esquema disponível.","trap":"Inversão.","review":"Piaget — assimilação"},{"id":"R4M09","kind":"Simulado","difficulty":"Médio","topic":"Piaget","stem":"Modificar o esquema para dar conta de uma informação nova é:","options":["assimilação.","acomodação.","centração.","afetividade."],"answer":1,"explanation":"Acomodação altera/reorganiza o esquema.","trap":"Inversão.","review":"Piaget — acomodação"},{"id":"R4M10","kind":"Simulado","difficulty":"Médio","topic":"Wallon","stem":"O conjunto “afeto, movimento, inteligência/cognição e pessoa” remete principalmente a:","options":["Vygotsky.","Piaget.","Wallon.","Skinner."],"answer":2,"explanation":"São campos funcionais/integrados da perspectiva walloniana.","trap":"Palavra inteligência pode distrair.","review":"Wallon — integração"},{"id":"R4M11","kind":"Simulado","difficulty":"Médio","topic":"Wallon","stem":"O estágio walloniano mais ligado à afirmação do eu entre cerca de 3 e 6 anos é:","options":["personalismo.","categorial.","pré-operatório.","sensório-motor."],"answer":0,"explanation":"Personalismo é a fase de afirmação da pessoa.","trap":"Pré-operatório é Piaget.","review":"Wallon — personalismo"},{"id":"R4M12","kind":"Simulado","difficulty":"Difícil","topic":"Wallon","stem":"Sobre alternância funcional, assinale a correta.","options":["Afetividade e cognição são mutuamente excludentes.","Há alternância de predominância, mantendo integração funcional.","Cada estágio elimina os anteriores.","Movimento deixa de ter papel após os 3 anos."],"answer":1,"explanation":"Wallon trabalha predominância alternante e integração.","trap":"Absolutização.","review":"Wallon — alternância"},{"id":"R4M13","kind":"Simulado","difficulty":"Difícil","topic":"Comparação","stem":"Qual afirmação é correta?","options":["Vygotsky e Piaget usam ZDP como conceito central.","Piaget e Wallon possuem modelos de estágios, mas com organizações e focos diferentes.","Wallon e Vygotsky ignoram a dimensão social.","Piaget reduz aprendizagem a reforço."],"answer":1,"explanation":"Piaget e Wallon descrevem estágios, mas não são equivalentes.","trap":"A palavra “estágio” não significa mesma teoria.","review":"Comparação dos autores"},{"id":"R4M14","kind":"Simulado","difficulty":"Difícil","topic":"Comparação","stem":"Qual alternativa contém uma troca conceitual?","options":["Vygotsky — internalização.","Piaget — conservação.","Wallon — afetividade.","Piaget — Zona de Desenvolvimento Proximal."],"answer":3,"explanation":"ZDP é vygotskiana.","trap":"Associação direta.","review":"Autor × conceito"},{"id":"R4M15","kind":"Simulado","difficulty":"Difícil","topic":"Educação Infantil","stem":"A educadora percebe que uma criança aprende uma sequência com ajuda de outra mais experiente e, semanas depois, passa a realizá-la sozinha. O autor mais diretamente relacionado é:","options":["Vygotsky.","Piaget apenas porque há sequência.","Wallon apenas porque há interação.","Skinner porque houve repetição."],"answer":0,"explanation":"O caso descreve passagem de desempenho assistido para independente, central à leitura pela ZDP.","trap":"Palavras genéricas como sequência/interação não superam o mecanismo descrito.","review":"Vygotsky — ZDP"},{"id":"R4M16","kind":"Simulado","difficulty":"Difícil","topic":"Piaget","stem":"Assinale a alternativa incorreta sobre o pré-operatório.","options":["Há função simbólica.","Pode ocorrer egocentrismo cognitivo.","A conservação lógica está plenamente consolidada.","O faz de conta ganha importância."],"answer":2,"explanation":"Conservação não está plenamente consolidada no pré-operatório.","trap":"Uma alternativa tecnicamente incompatível entre três verdadeiras.","review":"Piaget — pré-operatório"},{"id":"R4M17","kind":"Simulado","difficulty":"Difícil","topic":"Wallon","stem":"Uma criança demonstra emoção intensamente pelo corpo e a emoção mobiliza o grupo. Essa descrição é mais próxima de qual ideia walloniana?","options":["Emoção como manifestação afetiva com expressão corporal e função relacional/social.","Emoção como ruído que deve ser eliminado da aprendizagem.","Separação entre ato motor e vida psíquica.","Predomínio exclusivo da lógica formal."],"answer":0,"explanation":"Wallon dá à emoção função expressiva e relacional, integrada ao corpo.","trap":"Tratar emoção como obstáculo puro.","review":"Wallon — emoção"},{"id":"R4M18","kind":"Simulado","difficulty":"Difícil","topic":"Vygotsky","stem":"Assinale a alternativa incorreta.","options":["Funções superiores têm história social e cultural.","Mediação pode envolver signos e instrumentos.","A aprendizagem inicia somente quando a criança entra na escola.","Interação com pares pode ter papel no desenvolvimento."],"answer":2,"explanation":"Aprendizagens e desenvolvimento ocorrem antes da escolarização; a escola tem papel específico, mas não inaugura a aprendizagem humana.","trap":"“Somente” torna a alternativa falsa.","review":"Vygotsky — desenvolvimento"},{"id":"R4M19","kind":"Simulado","difficulty":"Difícil","topic":"Piaget × Wallon","stem":"A expressão “egocentrismo” pertence principalmente ao vocabulário de ______; “personalismo”, ao de ______.","options":["Wallon; Piaget.","Piaget; Wallon.","Vygotsky; Wallon.","Piaget; Vygotsky."],"answer":1,"explanation":"Egocentrismo cognitivo é piagetiano; personalismo é estágio walloniano.","trap":"Termos da mesma faixa etária podem parecer sinônimos.","review":"Piaget × Wallon"},{"id":"R4M20","kind":"Simulado","difficulty":"Difícil","topic":"Síntese","stem":"Uma prática pedagógica coerente com o conjunto das contribuições estudadas deve:","options":["tratar a criança como receptora de informação e separar emoção de cognição.","considerar atividade da criança, interação/mediação, condições do meio e desenvolvimento integral, sem fundir as teorias como se fossem iguais.","abandonar planejamento para preservar espontaneidade.","esperar maturação completa antes de oferecer desafios."],"answer":1,"explanation":"A síntese respeita diferenças entre as teorias e evita práticas passivas, fragmentadas ou maturacionistas rígidas.","trap":"A boa síntese não apaga diferenças teóricas.","review":"Síntese do Rank 4"}]};
    const FLASHCARDS=[["Quais são os dois eixos estruturantes?", "Interações e brincadeira."], ["Quais são os seis direitos?", "Conviver, brincar, participar, explorar, expressar e conhecer-se."], ["O que caracteriza a criança nas DCNEI?", "Sujeito histórico e de direitos que produz cultura e constrói sentidos."], ["Qual é o papel central do professor?", "Planejar condições, observar, escutar, mediar, ampliar experiências e registrar."], ["Brincadeira livre dispensa planejamento?", "Não. Liberdade infantil não significa ausência de intencionalidade educativa."], ["O que significa EI no código?", "Etapa da Educação Infantil."], ["O que significa 01 no código?", "Bebês: zero a 1 ano e 6 meses."], ["O que significa 02 no código?", "Crianças bem pequenas: 1 ano e 7 meses a 3 anos e 11 meses."], ["O que significa 03 no código?", "Crianças pequenas: 4 anos a 5 anos e 11 meses."], ["O que significa EO?", "O eu, o outro e o nós."], ["O que significa CG?", "Corpo, gestos e movimentos."], ["O que significa TS?", "Traços, sons, cores e formas."], ["O que significa EF?", "Escuta, fala, pensamento e imaginação."], ["O que significa ET?", "Espaços, tempos, quantidades, relações e transformações."], ["Os códigos indicam hierarquia?", "Não. Identificam objetivos; a sequência numérica não cria ordem obrigatória."], ["Como é a avaliação na Educação Infantil?", "Processual, por observação e registros, sem seleção, promoção, classificação ou retenção."], ["Exemplos de registros?", "Relatórios, portfólios, fotografias, desenhos, álbuns, falas e produções das crianças."], ["Cuidar e educar podem ser separados?", "Não. São dimensões indissociáveis."], ["O que são princípios éticos?", "Autonomia, responsabilidade, solidariedade e respeito ao bem comum, ambiente, culturas e singularidades."], ["O que são princípios políticos?", "Cidadania, criticidade e respeito à ordem democrática."], ["O que são princípios estéticos?", "Sensibilidade, criatividade, ludicidade e liberdade de expressão artística e cultural."], ["Transição significa antecipar conteúdos?", "Não. Significa continuidade, acolhimento e respeito às especificidades etárias."], ["A síntese das aprendizagens é pré-requisito?", "Não. É balizadora, não exame de prontidão."], ["Campo de experiência é disciplina?", "Não. É arranjo curricular integrado baseado em experiências concretas."], ["O que a rotina deve equilibrar?", "Previsibilidade e flexibilidade, respeitando ritmos, participação e imprevistos."], ["Inclusão exige o quê?", "Acessibilidade, eliminação de barreiras, participação e pertencimento ao grupo."], ["Como mediar conflito?", "Escutar, nomear sentimentos e apoiar negociação, sem autoritarismo nem omissão."], ["Tecnologia substitui experiências corporais?", "Não. Pode integrar experiências planejadas, sem consumo passivo ou substituição das demais linguagens."]];
    const LDB_FLASHCARDS=[["Art. 1º: onde a educação acontece?","Família, convivência humana, trabalho, instituições, movimentos/organizações sociais e manifestações culturais."],["A educação escolar deve vincular-se a quê?","Ao mundo do trabalho e à prática social."],["Três finalidades do art. 2º?","Pleno desenvolvimento do educando; cidadania; qualificação para o trabalho."],["Quem tem o dever da educação no art. 2º?","Família e Estado."],["Art. 3º: acesso?","Igualdade de condições para acesso e permanência na escola."],["Art. 3º: ideias pedagógicas?","Pluralismo de ideias e de concepções pedagógicas."],["Art. 3º: tolerância?","Respeito à liberdade e apreço à tolerância."],["Faixa da educação básica obrigatória?","Dos 4 aos 17 anos."],["Até que idade a EI é gratuita?","Até 5 anos."],["A partir de que idade responsáveis devem matricular?","4 anos."],["Educação básica obrigatória é que tipo de direito?","Direito público subjetivo."],["Município prioriza qual etapa?","Ensino Fundamental, além de oferecer Educação Infantil."],["Novidade art. 11 V em 2026?","EI municipal em zonas urbanas e rurais, proporcionalmente à distribuição populacional."],["Art. 12: quem elabora e executa a proposta pedagógica?","O estabelecimento de ensino."],["Art. 13: qual a relação do docente com a proposta?","Participa da elaboração e faz seu plano de trabalho segundo ela."],["Art. 13: seis núcleos?","Proposta; plano; aprendizagem; recuperação; dias/horas + planejamento/avaliação/desenvolvimento; família/comunidade."],["Art. 12 VIII: faltas para Conselho Tutelar?","Acima de 30% do percentual permitido em lei."],["Art. 14: dois princípios?","Profissionais no projeto pedagógico; comunidades escolar/local nos Conselhos e Fóruns."],["Educação Básica é formada por?","Educação Infantil, Ensino Fundamental e Ensino Médio."],["Art. 24 aplica suas regras comuns a quais níveis?","Ensino Fundamental e Ensino Médio."],["Frequência mínima art. 24?","75% para aprovação no EF/EM."],["Creche: idade?","Até 3 anos."],["Pré-escola: idade?","4 e 5 anos."],["Art. 29: quatro aspectos?","Físico, psicológico, intelectual e social."],["Art. 31: avaliação?","Acompanhamento e registro, sem promoção, inclusive para acesso ao EF."],["Art. 31: carga anual?","800 horas em pelo menos 200 dias."],["Art. 31: parcial e integral?","Mínimo de 4h parcial e 7h integral."],["Art. 31: frequência pré-escola?","60% do total de horas."],["Art. 31: documentação?","Deve atestar processos de desenvolvimento e aprendizagem."],["Ensino Fundamental começa aos?","6 anos."],["Educação Especial: palavra-chave?","Preferencialmente na rede regular."],["Art. 61 §2: nome do cargo é decisivo?","Não. A norma diz independentemente da designação, desde que cumpridos os requisitos."],["Art. 61 §2: requisitos?","Função docente direta com crianças + formação no magistério/superior + concurso público."],["Art. 62: mínimo admitido para EI?","Nível médio, modalidade Normal."],["Mnemônico art. 31?","A–800–200–4/7–60–D."]];
    const ECA_FLASHCARDS=[["Art. 1º: qual é a doutrina central?","Proteção integral."],["Criança para o ECA?","Pessoa até 12 anos de idade incompletos."],["Adolescente para o ECA?","Pessoa entre 12 e 18 anos de idade."],["Art. 4º: quem deve assegurar direitos?","Família, comunidade, sociedade em geral e poder público."],["Quatro ideias da prioridade absoluta?","Primazia, precedência, preferência e destinação privilegiada de recursos."],["Art. 5º protege contra quê?","Negligência, discriminação, exploração, violência, crueldade e opressão."],["Art. 6º: condição peculiar?","Criança e adolescente são pessoas em desenvolvimento."],["Art. 16 inclui brincar?","Sim: brincar, praticar esportes e divertir-se integra o direito à liberdade."],["Art. 17: três integridades protegidas?","Física, psíquica e moral."],["Castigo físico exige o quê?","Uso de força física + sofrimento físico OU lesão."],["Tratamento cruel/degradante?","Conduta que humilhe, ameace gravemente ou ridicularize."],["Quem aplica medidas do art. 18-B?","Conselho Tutelar."],["Art. 13 exige confirmação?","Não. Suspeita OU confirmação deve ser comunicada."],["Art. 13: comunicar a quem?","Ao Conselho Tutelar da respectiva localidade."],["Reavaliação do acolhimento: prazo?","No máximo a cada 3 meses."],["Acolhimento institucional: regra de prazo?","Não mais que 18 meses, salvo necessidade fundamentada no superior interesse."],["Pobreza basta para perda do poder familiar?","Não."],["Art. 22 atualizado: deveres?","Sustento, guarda, convivência, assistência material e afetiva e educação."],["Família substituta: três modalidades?","Guarda, tutela e adoção."],["Art. 53: estudante pode contestar avaliação?","Sim, podendo recorrer às instâncias escolares superiores."],["Art. 53: pais têm qual direito?","Ciência do processo pedagógico e participação na definição das propostas educacionais."],["Art. 54: creche/pré-escola qual faixa?","Zero a cinco anos."],["Ensino obrigatório e gratuito é que tipo de direito?","Direito público subjetivo."],["Art. 55: obrigação de quem?","Pais ou responsável matriculam filhos/pupilos na rede regular."],["Art. 56: faltas/evasão quando comunicar?","Quando reiteradas, injustificadas e após esgotados os recursos escolares."],["Art. 56: novidade 2025?","Negligência, abuso ou abandono."],["Art. 59-A trata de quê?","Fichas/certidões de antecedentes de colaboradores de instituições abrangidas."],["Art. 98: três origens da ameaça/violação?","Sociedade/Estado; pais/responsável; própria conduta."],["Art. 99: medidas podem acumular?","Sim, isolada ou cumulativamente e podem ser substituídas."],["CT no art. 131?","Permanente, autônomo e não jurisdicional."],["Quantos conselheiros tutelares?","5 membros."],["Mandato do conselheiro?","4 anos."],["Idade para candidatura?","Superior a 21 anos."],["Outros requisitos do art. 133?","Idoneidade moral e residência no município."],["CT pode requisitar serviços?","Sim, inclusive saúde, educação, assistência social, previdência, trabalho e segurança."],["Quem revisa decisão do CT?","Autoridade judiciária, a pedido de legítimo interessado."],["Ato infracional: definição?","Conduta descrita como crime ou contravenção penal."],["Ato infracional praticado por criança?","Aplicam-se medidas do art. 101."],["Art. 245 alcança Educ. Infantil?","Sim: menciona professor, pré-escola e creche."],["Multa do art. 245?","3 a 20 salários de referência, em dobro na reincidência."]];

    QUESTION_SETS.r5adapted = [{"id":"R5A01","kind":"Adaptada","difficulty":"Média","topic":"DCNEI","stem":"A avaliação do desenvolvimento na Educação Infantil NÃO deve ter como objetivo:","options":["acompanhar trajetórias.","subsidiar revisão das práticas.","selecionar, promover ou classificar crianças.","utilizar observação e registros."],"answer":2,"explanation":"As DCNEI afastam seleção, promoção e classificação como finalidade da avaliação.","trap":"A alternativa errada usa verbos incompatíveis com a EI.","review":"DCNEI art. 10"},{"id":"R5A02","kind":"Adaptada","difficulty":"Média","topic":"Avaliação diagnóstica","stem":"A avaliação diagnóstica tem como função principal:","options":["definir quem será retido.","levantar conhecimentos, experiências e necessidades para orientar intervenções.","atribuir a nota final.","comparar o estudante com a média da turma."],"answer":1,"explanation":"Diagnosticar é conhecer o ponto de partida para planejar e intervir.","trap":"Diagnóstico não é seleção.","review":"Modalidades de avaliação"},{"id":"R5A03","kind":"Adaptada","difficulty":"Média","topic":"Hoffmann","stem":"Na perspectiva mediadora de Hoffmann, o erro da criança deve ser entendido principalmente como:","options":["prova de incapacidade.","evidência a ser investigada para compreender hipóteses e orientar novas ações.","comportamento a ser ignorado.","motivo para punição pedagógica."],"answer":1,"explanation":"O erro fornece pistas sobre o processo de construção e pode orientar mediações.","trap":"Valorizar o erro não é abandoná-lo sem intervenção.","review":"Hoffmann — erro"},{"id":"R5A04","kind":"Adaptada","difficulty":"Média","topic":"LDB","stem":"Segundo a LDB, na Educação Infantil a avaliação ocorre mediante:","options":["prova semestral obrigatória.","acompanhamento e registro do desenvolvimento, sem objetivo de promoção.","nota mínima para o Ensino Fundamental.","classificação por níveis de maturidade."],"answer":1,"explanation":"O art. 31, I, estabelece acompanhamento e registro sem objetivo de promoção.","trap":"A banca pode trocar acompanhamento por exame ou promoção.","review":"LDB art. 31"},{"id":"R5A05","kind":"Adaptada","difficulty":"Média","topic":"Registros","stem":"Assinale a alternativa coerente com as DCNEI.","options":["Somente adultos podem produzir registros válidos.","Múltiplos registros podem ser produzidos por adultos e crianças.","Apenas relatórios escritos possuem valor avaliativo.","Fotografias substituem observação e interpretação."],"answer":1,"explanation":"As DCNEI preveem múltiplos registros produzidos por adultos e crianças.","trap":"“Somente” costuma tornar a alternativa falsa.","review":"DCNEI — registros"},{"id":"R5A06","kind":"Adaptada","difficulty":"Média","topic":"Observação","stem":"Uma observação avaliativa de qualidade deve:","options":["rotular traços de personalidade.","descrever ações em contexto e acompanhar mudanças ao longo do tempo.","ser feita apenas quando há problema.","comparar cada criança com a melhor da turma."],"answer":1,"explanation":"Descrição contextualizada produz evidências mais úteis que rótulos.","trap":"“É tímido/agressivo” não descreve o que ocorreu.","review":"Observação"},{"id":"R5A07","kind":"Adaptada","difficulty":"Difícil","topic":"Documentação","stem":"Qual situação melhor caracteriza documentação pedagógica?","options":["Guardar todas as fotos em uma pasta.","Selecionar registros, contextualizá-los, relacioná-los e interpretá-los para compreender a trajetória.","Preencher ficha de presença.","Expor apenas os melhores trabalhos."],"answer":1,"explanation":"Documentação implica seleção, contexto, interpretação e comunicação.","trap":"Acúmulo de material não é documentação.","review":"Documentação pedagógica"},{"id":"R5A08","kind":"Adaptada","difficulty":"Média","topic":"Formativa","stem":"A avaliação formativa caracteriza-se por:","options":["ocorrer apenas ao final.","produzir informação durante o processo para orientar intervenção e replanejamento.","ter função de ranking.","ser necessariamente quantitativa."],"answer":1,"explanation":"A formativa acompanha o percurso e regula a ação pedagógica.","trap":"Final do período sugere função somativa.","review":"Modalidades de avaliação"},{"id":"R5A09","kind":"Adaptada","difficulty":"Média","topic":"Relatório","stem":"Em relatório de Educação Infantil, a formulação mais adequada é:","options":["Lucas é desobediente e imaturo.","Lucas, nas brincadeiras coletivas, passou a negociar turnos com apoio e já propõe combinações aos colegas.","Lucas está abaixo do esperado e deve amadurecer.","Lucas é o mais difícil da turma."],"answer":1,"explanation":"A frase descreve ações, contexto e mudança sem rótulo.","trap":"Adjetivos globais cristalizam a criança.","review":"Relatórios"},{"id":"R5A10","kind":"Adaptada","difficulty":"Difícil","topic":"Hoffmann","stem":"Avaliação mediadora NÃO significa:","options":["acompanhar e interpretar manifestações.","reorganizar a ação pedagógica.","deixar a criança sem intervenção para respeitar seu ritmo.","criar situações desafiadoras."],"answer":2,"explanation":"Mediação exige intervenção intencional, não ausência do professor.","trap":"A palavra “respeitar o ritmo” pode mascarar passividade docente.","review":"Hoffmann — mediação"},{"id":"R5A11","kind":"Adaptada","difficulty":"Média","topic":"DCNEI","stem":"A documentação avaliativa na Educação Infantil deve permitir especialmente:","options":["ranquear crianças.","às famílias conhecer o trabalho da instituição e processos de desenvolvimento e aprendizagem.","definir aprovação.","selecionar para turmas avançadas."],"answer":1,"explanation":"Esse é um dos pontos expressos no art. 10 das DCNEI.","trap":"Documentação não é mecanismo seletivo.","review":"DCNEI — famílias"},{"id":"R5A12","kind":"Adaptada","difficulty":"Média","topic":"Transição","stem":"Na passagem para o Ensino Fundamental, a avaliação da Educação Infantil deve:","options":["produzir teste de prontidão.","favorecer continuidade por documentação e estratégias de transição, sem requisito seletivo.","reter quem não alfabetizou.","substituir brincadeiras por simulados."],"answer":1,"explanation":"As DCNEI tratam continuidade nas transições sem retenção.","trap":"Continuidade não é prontidão seletiva.","review":"Transição"},{"id":"R5A13","kind":"Adaptada","difficulty":"Média","topic":"Portfólio","stem":"Um portfólio coerente com avaliação mediadora deve:","options":["conter somente trabalhos corretos.","evidenciar processos, tentativas, mudanças e produções significativas ao longo do tempo.","ser igual para todas as crianças.","servir para calcular média."],"answer":1,"explanation":"O valor do portfólio está em tornar visível a trajetória.","trap":"“Melhores trabalhos” transforma processo em vitrine.","review":"Instrumentos — portfólio"},{"id":"R5A14","kind":"Adaptada","difficulty":"Difícil","topic":"Avaliar × registrar","stem":"Assinale a afirmação correta.","options":["Registrar e avaliar são exatamente a mesma coisa.","O registro fornece evidências; avaliar exige interpretação e decisão pedagógica.","Avaliar dispensa registro.","Quanto mais registros, melhor a avaliação automaticamente."],"answer":1,"explanation":"Registro é matéria-prima; avaliação envolve análise e uso pedagógico.","trap":"Quantidade não substitui qualidade.","review":"Avaliar × registrar"},{"id":"R5A15","kind":"Adaptada","difficulty":"Média","topic":"Síntese","stem":"A sequência mais coerente com uma avaliação mediadora é:","options":["provar → pontuar → classificar → arquivar.","observar → registrar → interpretar → intervir → replanejar → acompanhar novamente.","comparar → ranquear → comunicar.","testar → reter → recuperar."],"answer":1,"explanation":"A lógica mediadora transforma evidências em ação e novo acompanhamento.","trap":"A banca pode oferecer sequências com verbos tradicionais.","review":"Ciclo avaliativo"}];
    QUESTION_SETS.r5authorial = [{"id":"R5U01","kind":"Autoral","difficulty":"Difícil","topic":"Observação","stem":"A professora registra: “Bia é egoísta”. Qual reescrita produz dado avaliativo mais útil?","options":["Bia é pouco solidária.","Durante a brincadeira com blocos, Bia manteve todas as peças consigo; após convite de uma colega, cedeu duas e continuou construindo em dupla.","Bia precisa melhorar seu comportamento.","Bia não sabe compartilhar."],"answer":1,"explanation":"A descrição identifica situação, ação e mudança sem transformar episódio em traço fixo.","trap":"Trocar um rótulo por outro não resolve.","review":"Observação descritiva"},{"id":"R5U02","kind":"Autoral","difficulty":"Difícil","topic":"Documentação","stem":"Uma professora possui 200 fotografias do semestre, mas nenhuma anotação de contexto. O problema principal é:","options":["fotografia não pode ser usada na EI.","a ausência de contextualização e interpretação limita o valor pedagógico dos registros.","o número de fotos é insuficiente.","apenas desenhos têm valor avaliativo."],"answer":1,"explanation":"Fotografia pode ser ótima evidência, mas precisa fazer parte de uma leitura intencional do processo.","trap":"O instrumento não é o problema; o uso é.","review":"Documentação pedagógica"},{"id":"R5U03","kind":"Autoral","difficulty":"Difícil","topic":"Erro","stem":"Uma criança diz que há “mais água” no copo alto após a transferência da mesma quantidade. A atitude avaliativa mais coerente é:","options":["marcar erro e explicar imediatamente conservação.","investigar seu raciocínio, propor novas comparações e acompanhar mudanças na explicação.","evitar o tema até amadurecer.","atribuir conceito insuficiente."],"answer":1,"explanation":"A avaliação mediadora usa a resposta para investigar a lógica da criança e planejar desafios.","trap":"Erro não é sentença nem algo a ignorar.","review":"Erro e intervenção"},{"id":"R5U04","kind":"Autoral","difficulty":"Difícil","topic":"Inclusão","stem":"Em uma atividade de percurso motor, uma criança com deficiência física participa usando apoio adaptado. Na avaliação, o professor deve principalmente:","options":["compará-la com crianças sem deficiência.","observar participação, estratégias, autonomia possível e barreiras/apoios do contexto.","retirá-la do registro para evitar comparação.","avaliar somente comportamento."],"answer":1,"explanation":"A avaliação acompanha participação e aprendizagem considerando condições de acesso.","trap":"Equidade não é excluir da avaliação.","review":"Avaliação inclusiva"},{"id":"R5U05","kind":"Autoral","difficulty":"Difícil","topic":"Relatório","stem":"Qual trecho revela uma inferência inadequadamente determinista?","options":["“Passou a narrar acontecimentos com maior sequência temporal.”","“Procura colegas para organizar brincadeiras de faz de conta.”","“Ainda não está pronta para o 1º ano e provavelmente terá dificuldade de alfabetização.”","“Em situações de contagem, começou a apontar um objeto por vez.”"],"answer":2,"explanation":"O relatório não deve prever fracasso nem funcionar como teste de prontidão.","trap":"Uma previsão pode soar técnica e ainda assim ser indevida.","review":"Relatórios e transição"},{"id":"R5U06","kind":"Autoral","difficulty":"Difícil","topic":"Modalidades","stem":"Uma observação realizada no início de um projeto para descobrir o que as crianças já sabem sobre insetos cumpre função predominantemente:","options":["somativa.","diagnóstica.","classificatória.","seletiva."],"answer":1,"explanation":"O objetivo é levantar saberes prévios para orientar o projeto.","trap":"“No início” ajuda, mas a função é definida pelo propósito.","review":"Avaliação diagnóstica"},{"id":"R5U07","kind":"Autoral","difficulty":"Difícil","topic":"Formativa","stem":"Durante um projeto, o professor percebe pelas falas que as crianças confundem sementes com frutos e reorganiza a exploração do dia seguinte. Isso exemplifica:","options":["avaliação formativa integrada ao planejamento.","avaliação somativa.","promoção automática.","mensuração padronizada."],"answer":0,"explanation":"O dado obtido durante o processo modifica a intervenção seguinte.","trap":"Formativa = informação usada no percurso.","review":"Avaliação formativa"},{"id":"R5U08","kind":"Autoral","difficulty":"Difícil","topic":"Hoffmann","stem":"Qual afirmação melhor expressa a ideia de mediação avaliativa?","options":["O professor aguarda a construção espontânea sem interferir.","O professor provoca, acompanha e reorganiza situações a partir das manifestações da criança.","O professor mede para conhecer objetivamente o nível final.","O professor evita perguntas para não induzir respostas."],"answer":1,"explanation":"Mediação combina acompanhamento e ação pedagógica intencional.","trap":"Mediar não é assistir passivamente.","review":"Hoffmann — mediação"},{"id":"R5U09","kind":"Autoral","difficulty":"Difícil","topic":"Critérios","stem":"Dizer que a avaliação mediadora possui critérios significa que:","options":["todas as crianças devem produzir o mesmo resultado no mesmo dia.","o professor observa com referências e objetivos claros, sem converter diferenças em ranking.","é necessário dar nota.","o critério deve ser secreto para evitar interferência."],"answer":1,"explanation":"Critério orienta o olhar e a decisão; não exige homogeneização.","trap":"Critério ≠ padronização rígida.","review":"Critérios avaliativos"},{"id":"R5U10","kind":"Autoral","difficulty":"Difícil","topic":"Criança autora","stem":"Uma prática coerente com “registros realizados por adultos e crianças” é:","options":["professor preencher ficha sozinho.","incluir desenhos, falas, escolhas e produções da criança na documentação, contextualizando-as.","pedir que a criança dê nota aos colegas.","deixar a avaliação inteiramente sob responsabilidade infantil."],"answer":1,"explanation":"A criança pode ser autora de registros sem assumir a função profissional de avaliação.","trap":"Participação não transfere responsabilidade pedagógica.","review":"Registros das crianças"},{"id":"R5U11","kind":"Autoral","difficulty":"Difícil","topic":"Comparação","stem":"Para acompanhar progresso individual, o referencial mais produtivo é:","options":["a criança em relação ao colega de maior desempenho.","a própria trajetória da criança, os objetivos e as condições oferecidas.","a média estatística da turma como critério único.","a idade cronológica isolada."],"answer":1,"explanation":"Acompanhamento olha mudanças na trajetória e referências pedagógicas sem ranking.","trap":"Individualização não é ausência de objetivos.","review":"Trajetória individual"},{"id":"R5U12","kind":"Autoral","difficulty":"Difícil","topic":"Família","stem":"Ao apresentar documentação à família, a escola deve:","options":["mostrar apenas dificuldades.","comunicar trajetórias e trabalho pedagógico, dialogando sem rótulos ou culpabilização.","pedir que a família confirme a nota.","omitir desafios para evitar conflito."],"answer":1,"explanation":"A documentação apoia transparência e parceria, com descrição equilibrada do processo.","trap":"Nem culpabilização nem ocultação.","review":"Devolutiva às famílias"},{"id":"R5U13","kind":"Autoral","difficulty":"Difícil","topic":"Checklist","stem":"Uma pauta de observação com vários itens torna-se classificatória quando:","options":["ajuda o professor a lembrar aspectos a observar.","vira lista rígida de normalidade e o resultado final se reduz a atingiu/não atingiu.","é combinada com notas de campo.","é revista ao longo do projeto."],"answer":1,"explanation":"O risco surge quando o instrumento substitui a interpretação e padroniza trajetórias.","trap":"O checklist não é automaticamente proibido.","review":"Instrumentos"},{"id":"R5U14","kind":"Autoral","difficulty":"Difícil","topic":"Replanejamento","stem":"A professora registra durante duas semanas que o mesmo grupo abandona rapidamente uma proposta de desenho. Antes de concluir “falta de interesse”, o melhor passo é:","options":["baixar nota de participação.","analisar materiais, tempo, organização, sentidos da proposta e testar novas condições.","obrigar permanência mínima.","eliminar desenho do currículo."],"answer":1,"explanation":"Avaliação também investiga a qualidade das condições pedagógicas oferecidas.","trap":"O problema pode estar no contexto, não na criança.","review":"Avaliação da prática"},{"id":"R5U15","kind":"Autoral","difficulty":"Difícil","topic":"Síntese","stem":"Qual alternativa reúne três características compatíveis com avaliação mediadora na EI?","options":["continuidade, investigação e replanejamento.","mensuração, ranking e retenção.","padronização, seleção e prova final.","neutralidade, passividade e espontaneísmo."],"answer":0,"explanation":"A avaliação mediadora é contínua, investigativa e orienta a ação futura.","trap":"Trincas de conceitos são formato típico de prova.","review":"Síntese Rank 5"}];
    QUESTION_SETS.r5mock = [{"id":"R5M01","kind":"Simulado","difficulty":"Difícil","topic":"Hoffmann","stem":"O paradigma que Hoffmann contrapõe ao modelo sentencioso/classificatório é o de avaliação:","options":["mediadora.","seletiva.","normativa.","meritocrática."],"answer":0,"explanation":"Hoffmann denomina mediadora a perspectiva que acompanha e intervém no processo.","trap":"Associação autor × conceito.","review":"Hoffmann"},{"id":"R5M02","kind":"Simulado","difficulty":"Difícil","topic":"LDB","stem":"Na Educação Infantil, a avaliação pode ser utilizada para promoção ao Ensino Fundamental quando houver documentação suficiente.","options":["Verdadeiro.","Falso.","Somente na pré-escola.","Somente por decisão da família."],"answer":1,"explanation":"A LDB afasta objetivo de promoção, inclusive para acesso ao Ensino Fundamental.","trap":"A expressão “documentação suficiente” não cria exceção.","review":"LDB art. 31"},{"id":"R5M03","kind":"Simulado","difficulty":"Difícil","topic":"DCNEI","stem":"Assinale o item que NÃO corresponde às garantias do art. 10 das DCNEI.","options":["Observação crítica e criativa.","Múltiplos registros de adultos e crianças.","Não retenção.","Classificação por níveis para organização das turmas."],"answer":3,"explanation":"Classificação não é finalidade da avaliação na EI.","trap":"Alternativa destoante.","review":"DCNEI art. 10"},{"id":"R5M04","kind":"Simulado","difficulty":"Difícil","topic":"Observação","stem":"“Rafaela é agressiva” é um registro fraco porque:","options":["usa verbo de ligação.","transforma episódios em traço global e não informa contexto observável.","não contém nota.","deveria comparar com colegas."],"answer":1,"explanation":"Registros avaliativos úteis descrevem ações e situações, evitando rótulos.","trap":"Questão prática de linguagem avaliativa.","review":"Observação"},{"id":"R5M05","kind":"Simulado","difficulty":"Difícil","topic":"Documentação","stem":"Registro e documentação pedagógica diferem porque:","options":["registro é sempre escrito; documentação é sempre visual.","documentação envolve seleção, contextualização e interpretação de registros.","documentação dispensa registros.","registro é só da criança."],"answer":1,"explanation":"Documentação transforma evidências em narrativa/reflexão pedagógica.","trap":"Não confunda suporte com função.","review":"Documentação"},{"id":"R5M06","kind":"Simulado","difficulty":"Difícil","topic":"Erro","stem":"Na avaliação mediadora, ao identificar erro persistente, o professor deve:","options":["não interferir.","investigar estratégias e criar novas situações de aprendizagem.","registrar para justificar retenção.","corrigir publicamente para fixar resposta."],"answer":1,"explanation":"O erro informa intervenção, não retenção ou humilhação.","trap":"Respeitar não é abandonar.","review":"Erro e mediação"},{"id":"R5M07","kind":"Simulado","difficulty":"Difícil","topic":"Modalidades","stem":"Qual associação está correta?","options":["Diagnóstica — classificação final.","Formativa — informação durante o processo para intervenção.","Somativa — sondagem inicial.","Diagnóstica — retenção."],"answer":1,"explanation":"A função formativa é regular o percurso.","trap":"Troca de definições.","review":"Modalidades"},{"id":"R5M08","kind":"Simulado","difficulty":"Difícil","topic":"Instrumentos","stem":"Sobre instrumentos avaliativos, assinale a correta.","options":["Portfólio é mediador por natureza.","Fotografia nunca é avaliação.","O valor do instrumento depende de finalidade, contexto, interpretação e uso pedagógico.","Checklist é sempre proibido."],"answer":2,"explanation":"Nenhum suporte garante concepção mediadora sozinho.","trap":"Evite absolutos “sempre/nunca”.","review":"Instrumentos"},{"id":"R5M09","kind":"Simulado","difficulty":"Difícil","topic":"Relatório","stem":"Qual trecho deve ser evitado em relatório?","options":["“Passou a esperar sua vez em alguns jogos coletivos.”","“Explora misturas de cores e comenta diferenças que observa.”","“É preguiçoso e pouco interessado.”","“Começou a pedir ajuda verbalmente em situações de dificuldade.”"],"answer":2,"explanation":"É rótulo global sem descrição contextual.","trap":"Adjetivos avaliativos podem mascarar julgamento.","review":"Relatórios"},{"id":"R5M10","kind":"Simulado","difficulty":"Difícil","topic":"Família","stem":"Segundo as DCNEI, a documentação específica deve permitir às famílias:","options":["conhecer trabalho institucional e processos de desenvolvimento/aprendizagem.","decidir quem será promovido.","alterar notas.","comparar a criança com a turma."],"answer":0,"explanation":"A comunicação às famílias é garantia explícita do art. 10.","trap":"Família participa, mas não cria mecanismo de promoção.","review":"DCNEI — famílias"},{"id":"R5M11","kind":"Simulado","difficulty":"Difícil","topic":"Replanejamento","stem":"Se o professor coleta dados avaliativos e mantém o planejamento inalterado independentemente do que observou, falta principalmente:","options":["pontuação.","uso pedagógico da avaliação para replanejamento.","prova final.","classificação."],"answer":1,"explanation":"Avaliação deve subsidiar decisões.","trap":"Coleta sem ação vira burocracia.","review":"Replanejamento"},{"id":"R5M12","kind":"Simulado","difficulty":"Difícil","topic":"Hoffmann","stem":"Qual opção é incompatível com Hoffmann?","options":["Avaliação como mediação.","Reflexão sobre manifestações do aluno.","Erro como informação para novas ações.","Nota como sentença suficiente do processo."],"answer":3,"explanation":"A perspectiva mediadora se opõe à redução do processo a sentença classificatória.","trap":"Uma alternativa rompe a lógica inteira.","review":"Hoffmann"},{"id":"R5M13","kind":"Simulado","difficulty":"Difícil","topic":"Portfólio","stem":"Um portfólio que contém somente a “melhor” produção de cada mês perde principalmente:","options":["beleza visual.","capacidade de mostrar processo, tentativas e transformações.","valor administrativo.","possibilidade de impressão."],"answer":1,"explanation":"A seleção deve tornar visível trajetória, não apenas resultado final.","trap":"“Melhor” pode esconder o processo.","review":"Portfólio"},{"id":"R5M14","kind":"Simulado","difficulty":"Difícil","topic":"Diagnóstica","stem":"Uma roda de conversa usada para levantar hipóteses antes de um projeto é avaliação diagnóstica mesmo sem teste escrito.","options":["Verdadeiro.","Falso.","Somente se houver nota.","Somente no Ensino Fundamental."],"answer":0,"explanation":"Função diagnóstica é definida pelo propósito de sondagem, não pelo formato.","trap":"Prova não é requisito.","review":"Diagnóstica"},{"id":"R5M15","kind":"Simulado","difficulty":"Difícil","topic":"Criança autora","stem":"A previsão de registros realizados por crianças significa que:","options":["elas assumem sozinhas a avaliação.","suas produções e perspectivas também podem compor evidências documentais.","o professor não registra.","a criança atribui nota a si mesma."],"answer":1,"explanation":"Autoria infantil amplia a documentação, sem retirar responsabilidade docente.","trap":"Participação ≠ transferência de função.","review":"Registros infantis"},{"id":"R5M16","kind":"Simulado","difficulty":"Difícil","topic":"Inclusão","stem":"Avaliar uma criança com deficiência de modo inclusivo implica:","options":["dispensá-la de acompanhamento.","considerar aprendizagens, participação, apoios e barreiras do contexto.","usar padrão único sem adaptação.","avaliar apenas diagnóstico clínico."],"answer":1,"explanation":"O acompanhamento deve observar o que a criança faz e as condições que favorecem ou impedem participação.","trap":"Diagnóstico clínico não substitui avaliação pedagógica.","review":"Avaliação inclusiva"},{"id":"R5M17","kind":"Simulado","difficulty":"Difícil","topic":"Transição","stem":"A documentação da pré-escola pode funcionar como requisito de ingresso no 1º ano.","options":["Verdadeiro.","Falso.","Somente se a escola aprovar.","Somente com autorização dos pais."],"answer":1,"explanation":"A transição deve preservar continuidade, não criar seleção ou promoção.","trap":"“Prontidão” é armadilha clássica.","review":"Transição"},{"id":"R5M18","kind":"Simulado","difficulty":"Difícil","topic":"Critérios","stem":"Avaliação mediadora e critérios são incompatíveis.","options":["Verdadeiro.","Falso, pois critérios orientam o olhar sem exigir classificação.","Verdadeiro na Educação Infantil apenas.","Depende de haver nota."],"answer":1,"explanation":"Mediação exige intencionalidade; isso inclui referências e critérios pedagógicos.","trap":"Não confunda não-classificação com ausência de rigor.","review":"Critérios"},{"id":"R5M19","kind":"Simulado","difficulty":"Difícil","topic":"Síntese","stem":"Qual sequência apresenta apenas ações coerentes com a avaliação na EI?","options":["observar, registrar, interpretar, intervir.","medir, ranquear, selecionar, reter.","testar, punir, classificar, promover.","comparar, rotular, separar, arquivar."],"answer":0,"explanation":"A sequência acompanha o processo e gera intervenção.","trap":"Sequência de verbos facilita eliminar alternativas.","review":"Síntese"},{"id":"R5M20","kind":"Simulado","difficulty":"Difícil","topic":"Caso prático","stem":"Uma professora percebe que uma proposta não favoreceu participação de várias crianças. A resposta mais coerente é:","options":["registrar baixa participação como falha das crianças.","rever espaço, tempo, materiais e mediação e oferecer nova experiência.","retirar as crianças do próximo projeto.","atribuir conceito de interesse."],"answer":1,"explanation":"Avaliação inclui reflexão sobre a própria prática e condições oferecidas.","trap":"O foco não é culpar a criança.","review":"Avaliação da prática"}];
    const R4_FLASHCARDS=[["Vygotsky: palavra-chave UniFil?","Mediação."],["Piaget: palavra-chave UniFil?","Epistemologia Genética."],["Wallon: palavra-chave UniFil?","Afetividade."],["ZDP: nível real?","O que a criança realiza de forma independente."],["ZDP: nível potencial?","O que consegue com orientação/colaboração adequada."],["ZDP é um terceiro nível isolado?","Não; é a zona/dinâmica entre possibilidades real e potencial."],["Mediação é só professor falando?","Não. Pode envolver pessoas, signos, instrumentos e organização da atividade."],["Funções psicológicas superiores?","Atenção voluntária, memória lógica, pensamento conceitual, planejamento e autorregulação, entre outras."],["Internalização?","Reconstrução interna de processos inicialmente constituídos nas relações sociais."],["Interpsicológico → ?","Intrapsicológico."],["Linguagem em Vygotsky?","Mediação simbólica central para comunicação, pensamento e autorregulação."],["Bom ensino em Vygotsky?","Não se limita ao já consolidado; pode mobilizar funções em vias de desenvolvimento."],["Piaget: quatro estágios?","Sensório-motor; pré-operatório; operações concretas; operações formais."],["Sensório-motor?","Ação e sentidos; progressiva permanência do objeto e intencionalidade."],["Pré-operatório?","Função simbólica, pensamento intuitivo, egocentrismo, centramento e dificuldade de conservação."],["Operações concretas?","Conservação, reversibilidade, classificação, seriação e lógica aplicada ao concreto."],["Operações formais?","Abstração e raciocínio hipotético-dedutivo."],["Assimilação?","Interpretar/incorporar o novo com esquemas existentes."],["Acomodação?","Modificar/reorganizar esquemas diante do novo."],["Equilibração?","Regulação dinâmica entre assimilação e acomodação rumo a novas organizações."],["Esquema em Piaget?","Estrutura de ação/pensamento que organiza a experiência."],["Egocentrismo = egoísmo?","Não. É dificuldade cognitiva de coordenar perspectivas."],["Conservação?","Compreender que uma quantidade pode permanecer apesar de transformação perceptiva."],["Wallon: quatro conjuntos funcionais?","Afetividade, movimento/ato motor, cognição/inteligência e pessoa."],["Afetividade = carinho?","Não. É campo funcional amplo que inclui emoções, sentimentos e paixões."],["Wallon: primeiro estágio?","Impulsivo-emocional."],["Wallon: 1–3 anos?","Sensório-motor e projetivo."],["Wallon: 3–6 anos?","Personalismo."],["Wallon: 6–11 anos?","Categorial."],["Wallon: adolescência?","Puberdade e adolescência, com nova predominância afetiva."],["Alternância funcional?","Mudam as predominâncias afetivas/cognitivas sem excluir as demais funções."],["Integração funcional?","Afetividade, movimento e cognição funcionam integradamente na pessoa."],["Meio em Wallon?","Participa dialeticamente do desenvolvimento junto às condições orgânicas e relações sociais."],["Piaget: professor ausente?","Não. Organiza desafios e experiências que favorecem construção."],["Vygotsky: criança passiva?","Não. A apropriação é ativa e mediada."],["Wallon: desenvolvimento linear?","Não. Há crises, alternâncias e reorganizações."],["Piaget × Wallon: egocentrismo/personalismo?","Egocentrismo é piagetiano; personalismo é walloniano."],["ZDP × assimilação?","ZDP = Vygotsky; assimilação = Piaget."],["Afetividade × mediação?","Afetividade = Wallon; mediação = Vygotsky."],["Meta do Rank 4?","Reconhecer autor pelo mecanismo, não só pelo nome."]];
    const R5_FLASHCARDS=[["Avaliação na EI: núcleo legal?","Acompanhamento e registro do desenvolvimento, sem objetivo de promoção."],["DCNEI: observação de quê?","Atividades, brincadeiras e interações no cotidiano, de forma crítica e criativa."],["Quem pode produzir registros segundo DCNEI?","Adultos e crianças."],["DCNEI e transições?","Criar estratégias para continuidade das aprendizagens nos diferentes momentos de transição."],["Documentação às famílias serve para quê?","Conhecer o trabalho da instituição e processos de desenvolvimento e aprendizagem."],["Retenção na Educação Infantil?","Não."],["Hoffmann: palavra-chave?","Mediação."],["Avaliação mediadora = professor passivo?","Não. Exige investigação, desafio, intervenção e replanejamento."],["Erro na avaliação mediadora?","Pista sobre hipóteses e estratégias; orienta novas ações."],["Diálogo avaliativo?","Relação investigativa que ajuda a explicitar e reorganizar ideias."],["Registrar = avaliar?","Não. Registro é evidência; avaliação requer interpretação e decisão."],["Registro = documentação pedagógica?","Não. Documentação seleciona, contextualiza, relaciona e interpreta registros."],["Foto isolada é documentação?","Não necessariamente; precisa de contexto e interpretação."],["Portfólio serve para quê?","Tornar visível processo, tentativas, mudanças e produções significativas."],["Portfólio deve ter só melhores trabalhos?","Não. Isso apaga o processo."],["Relatório bom usa rótulos?","Não. Descreve ações, contextos e trajetórias."],["Exemplo de rótulo a evitar?","“É preguiçoso”, “é agressivo”, “é imaturo”."],["Observação intencional pergunta o quê?","O que observar, em qual contexto, com quem/materiais e o que mudou no tempo."],["Diagnóstica: função?","Levantar ponto de partida, saberes, experiências e necessidades."],["Formativa: função?","Acompanhar durante o processo e orientar intervenção/replanejamento."],["Somativa: função geral?","Sintetizar resultados ao final; não deve ser confundida com promoção/retenção na EI."],["Avaliar × medir?","Medir quantifica; avaliar interpreta dados para orientar decisões."],["Avaliar × classificar?","Classificar ordena/categoriza; avaliar na EI acompanha sem seleção."],["Critério = ranking?","Não. Critério orienta observação e interpretação."],["Individualidade = ausência de objetivos?","Não. Acompanhar singularmente não elimina referências pedagógicas."],["A criança pode participar da documentação?","Sim, por produções, falas, escolhas e outros registros."],["Quem é responsável pela avaliação pedagógica?","A instituição e os profissionais; participação infantil não transfere essa responsabilidade."],["Avaliação deve mudar o planejamento?","Sim. Dados devem gerar decisões pedagógicas."],["Ciclo mediador?","Observar → registrar → interpretar → intervir → replanejar → reobservar."],["O que é observação fraca?","Rótulo sem contexto ou episódio isolado tratado como traço fixo."],["O que é registro anedótico?","Descrição datada e contextualizada de episódio significativo."],["Checklist pode ser usado?","Pode apoiar observação, mas não deve virar padrão rígido/único de normalidade."],["Desenho permite diagnóstico psicológico automático?","Não."],["Família deve conhecer apenas dificuldades?","Não. A devolutiva aborda trajetória, aprendizagens, desafios e trabalho pedagógico."],["Transição para 1º ano = teste de prontidão?","Não."],["Alfabetização formal é requisito de promoção na pré-escola?","Não."],["Avaliação inclusiva considera o quê?","Aprendizagem, participação, apoios e barreiras do contexto."],["Erro deve ser ignorado para não frustrar?","Não. Deve ser investigado e mediado."],["Quantidade de registros = qualidade?","Não. Relevância, contexto e interpretação importam mais."],["Meta do Rank 5?","Transformar evidências em compreensão e ação pedagógica, sem classificar a criança."]];
/* Rank 6 — Kishimoto, jogo, brinquedo e brincadeira */
const R6_FLASHCARDS=[
['Como as DCNEI definem a criança?','Sujeito histórico e de direitos, centro do planejamento curricular, que produz cultura nas relações e práticas cotidianas.'],
['O que é currículo na Educação Infantil segundo as DCNEI?','Conjunto de práticas que articula experiências e saberes das crianças aos patrimônios cultural, artístico, ambiental, científico e tecnológico.'],
['Quais são os eixos das práticas pedagógicas da Educação Infantil?','Interações e brincadeira.'],
['Jogo, brinquedo e brincadeira são sinônimos?','Não. O jogo é uma prática com significados e, frequentemente, regras; brinquedo é o objeto ou suporte; brincadeira é a ação lúdica realizada pela criança.'],
['Qual característica impede reconhecer uma atividade como brincadeira genuína?','A ausência de escolha e de decisão da criança, quando toda a ação e o resultado são rigidamente impostos.'],
['O que é função lúdica?','Prazer, interesse, expressão, escolha e envolvimento do brincante.'],
['O que é função educativa?','Possibilidade de ampliar aprendizagens e desenvolvimento por meio da experiência.'],
['As funções lúdica e educativa são incompatíveis?','Não. Podem coexistir, desde que a intenção adulta não elimine a agência e o caráter lúdico.'],
['O brinquedo determina uma única forma de uso?','Não. A criança atribui significados e pode reinventar o objeto conforme sua cultura e imaginação.'],
['O que são materiais não estruturados?','Objetos abertos a múltiplos usos, como caixas, tecidos, tampas, argila e elementos naturais.'],
['O que caracteriza o faz de conta?','A criação de uma situação imaginária, atribuição de papéis e substituição simbólica de objetos e ações.'],
['Brincadeira livre significa ausência total do professor?','Não. O professor organiza condições, observa, garante segurança e pode ampliar a experiência sem controlá-la.'],
['Qual é o papel do educador no brincar?','Planejar tempos, espaços e materiais; observar; documentar; incluir; proteger e intervir com intencionalidade.'],
['Qual é o papel da criança no currículo?','Participante ativa, competente, produtora de cultura e sentidos, não receptora passiva.'],
['Brincar é recompensa depois da atividade séria?','Não. É direito de aprendizagem, linguagem da infância e eixo estruturante.'],
['Jogo educativo é apenas uma ficha com aparência divertida?','Não. Precisa preservar participação significativa, desafio e dimensão lúdica; exercício disfarçado pode não constituir jogo.'],
['O que a repetição produz na brincadeira?','Aprofundamento, domínio, elaboração emocional e criação de novas variações.'],
['Conflito durante uma brincadeira é sempre fracasso?','Não. Pode favorecer negociação, linguagem, compreensão de regras e convivência, com mediação quando necessária.'],
['Como incluir sem empobrecer a experiência?','Removendo barreiras e oferecendo diferentes formas de participação, comunicação, apoio e acesso aos materiais.'],
['O que observar no brincar?','Escolhas, parceiros, enredos, linguagens, hipóteses, estratégias, emoções, negociações e modos de usar espaço e materiais.'],
['O produto final é o principal na Educação Infantil?','Não. O processo, a participação, as interações e os sentidos construídos têm centralidade.'],
['Qual relação existe entre brincar e cultura?','A criança apropria-se de elementos culturais e também os recria, produzindo cultura infantil.'],
['Toda atividade divertida é pedagógica?','Não automaticamente. A qualidade depende de objetivos, contexto, participação, mediação e experiências promovidas.'],
['O professor deve corrigir imediatamente todo enredo imaginário?','Não. O faz de conta opera simbolicamente; a intervenção depende de risco, violação de direitos ou oportunidade real de ampliação.'],
['Como evitar estereótipos nos brinquedos?','Diversificar representações, materiais, papéis e narrativas e problematizar exclusões sem proibir a criação infantil.'],
['O que é escuta pedagógica?','Atenção às falas, gestos, silêncios, escolhas, movimentos e produções das crianças para compreender e replanejar.'],
['Intencionalidade equivale a dirigir cada ação?','Não. É organizar e intervir com propósito, preservando iniciativa, curiosidade e participação infantil.'],
['Rotina e ludicidade são opostas?','Não. Uma rotina previsível e flexível pode garantir tempo contínuo e segurança para brincar.'],
['O brincar pode ser usado só para diagnosticar?','Não. A observação informa o planejamento, mas a brincadeira não deve ser reduzida a teste.'],
['Qual pegadinha envolve alfabetização na Educação Infantil?','Confundir experiências significativas com a linguagem escrita com treino mecânico, antecipação escolarizante e cópia repetitiva.'],
['O que diferencia regra negociada de obediência cega?','A regra negociada é compreendida e construída na participação; obediência cega apenas submete a criança à ordem externa.'],
['Qual síntese memorizar para a prova?','Criança ativa; currículo de experiências; professor intencional; interações e brincadeira; cuidado e educação indissociáveis.']
];

