/* Rank 7 — Educação Inclusiva e Educação Especial */
const R7_FLASHCARDS=[
['Inclusão e integração são sinônimos?','Não. Na integração, o estudante deve adaptar-se ao sistema; na inclusão, o sistema identifica e remove barreiras.'],
['Educação Especial é etapa de ensino?','Não. É modalidade transversal aos níveis, etapas e modalidades.'],
['Quem é o público da Educação Especial?','Pessoas com deficiência, transtorno do espectro autista e altas habilidades ou superdotação.'],
['O que é AEE?','Atividade pedagógica que organiza recursos e acessibilidade para eliminar barreiras e ampliar participação e aprendizagem.'],
['AEE substitui a classe comum?','Não. A matrícula e a frequência no AEE não substituem a classe comum.'],
['AEE é complementar para quem?','Pessoas com deficiência e TEA.'],
['AEE é suplementar para quem?','Pessoas com altas habilidades ou superdotação.'],
['AEE é reforço escolar?','Não. Seu foco são barreiras, recursos pedagógicos e acessibilidade.'],
['AEE é atendimento clínico?','Não. É atendimento de natureza pedagógica, articulado a outras políticas quando necessário.'],
['A oferta do AEE depende de laudo médico?','Não. Não pode ser condicionada a diagnóstico, laudo ou documento de profissional da saúde.'],
['O que inicia o planejamento do AEE?','Estudo de caso: demandas, contexto, barreiras, potencialidades, apoios e recursos.'],
['O que são PAEE e PEI?','Documentos individualizados, pedagógicos e continuamente atualizados, derivados do estudo de caso e integrados ao PPP.'],
['Qual documento orienta especificamente o AEE?','PAEE — Plano de Atendimento Educacional Especializado.'],
['Qual documento articula sala comum, AEE e colaboração?','O PEI, conjuntamente com o PAEE na regulamentação atual.'],
['O que é acessibilidade?','Condição de alcance e uso seguro e autônomo de espaços, informação, comunicação, tecnologias e serviços.'],
['O que é desenho universal?','Concepção de ambientes, produtos e serviços utilizáveis pelo maior número de pessoas sem adaptação específica.'],
['O que é adaptação razoável?','Ajuste necessário e adequado, sem ônus desproporcional, requerido em caso concreto.'],
['O que é tecnologia assistiva?','Recursos, estratégias, práticas e serviços que promovem funcionalidade, autonomia e participação.'],
['O que é barreira atitudinal?','Atitude ou comportamento que impede ou prejudica participação em igualdade de condições.'],
['O que é barreira comunicacional?','Obstáculo à expressão ou ao recebimento de mensagens e informações.'],
['O currículo deve ser reduzido automaticamente?','Não. Primeiro removem-se barreiras, diversificam-se meios e preservam-se expectativas de aprendizagem.'],
['Igualdade e equidade são idênticas?','Não. Equidade reconhece necessidades e oferece apoios para garantir direitos e participação.'],
['O profissional de apoio substitui o professor?','Não. Apoia atividades necessárias; planejamento e docência permanecem responsabilidades pedagógicas.'],
['Família decide sozinha a prática escolar?','Não. Participa e compartilha informações, em diálogo com equipe e estudante.'],
['A inclusão é responsabilidade apenas do AEE?','Não. É responsabilidade institucional e envolve gestão, sala comum, AEE, família e rede.'],
['Qual o erro de “ele não acompanha a turma”?','Usar um padrão único como medida e atribuir o problema à criança, sem analisar barreiras e apoios.'],
['Como avaliar na perspectiva inclusiva?','Com instrumentos diversificados, acessíveis e coerentes com objetivos, sem confundir apoio com facilitação indevida.'],
['Altas habilidades significam bom desempenho em tudo?','Não. Podem aparecer em áreas específicas e coexistir com dificuldades ou deficiência.'],
['TEA implica incapacidade de interação?','Não. Há grande variabilidade; devem-se conhecer modos de comunicação, interesses, barreiras e apoios individuais.'],
['Qual palavra-chave da LDB sobre oferta?','Preferencialmente na rede regular de ensino.'],
['Qual sequência mental resolve casos?','Identificar barreira → reconhecer potencialidades → planejar apoio → garantir participação → acompanhar e revisar.'],
['Qual síntese memorizar?','Acesso não basta: inclusão exige permanência, participação, aprendizagem e pertencimento.']
];

