/* Rank 8 — Referencial Curricular do Paraná */
const R8_FLASHCARDS=[
['Qual é a função do RCP?','Orientar a elaboração e reorganização dos currículos paranaenses, acrescentando contexto estadual às definições da BNCC.'],
['O RCP substitui a BNCC?','Não. Dialoga com ela, mantém seus fundamentos e acrescenta detalhamentos para o território paranaense.'],
['O RCP é um plano de aula pronto?','Não. É referência para currículos, PPP, propostas e planejamento contextualizado.'],
['Quando o RCP foi construído?','Em 2018, com regime de colaboração e consulta pública; consolidado e normatizado posteriormente.'],
['Qual norma estadual institui o RCP?','Deliberação CEE/PR nº 03/2018.'],
['Quais são as cinco seções da Educação Infantil?','História; princípios e direitos; concepções; articulação EI–EF; organizador curricular.'],
['Quais são os eixos?','Interações e brincadeira.'],
['Quais são os seis direitos?','Conviver, brincar, participar, explorar, expressar e conhecer-se.'],
['Quais são os cinco campos?','EO; CG; TS; EF; ET.'],
['Princípios éticos associam-se a quais direitos?','Conhecer-se e conviver.'],
['Princípios políticos associam-se a quais direitos?','Expressar e participar.'],
['Princípios estéticos associam-se a quais direitos?','Brincar e explorar.'],
['Como a BNCC agrupa idades?','Três grupos: bebês, crianças bem pequenas e crianças pequenas.'],
['Como o RCP detalha idades?','Seis partes: 0, 1, 2, 3, 4 e 5 anos.'],
['O detalhamento por idade autoriza rigidez?','Não. Complexidade e objetivos acompanham ritmos e desenvolvimento individual.'],
['O que acontece com objetivos da BNCC no organizador?','Aparecem com código original, destacados, seguidos de complementações/objetivos correlacionados do Paraná.'],
['O que o RCP acrescenta ao organizador?','Saberes e conhecimentos relacionados aos objetivos, reforçando intencionalidade e conhecimento sistematizado.'],
['Por que alguns objetivos se repetem?','Porque os grupos da BNCC foram desdobrados por idade e a complexidade deve crescer gradativamente.'],
['Campos de experiências são disciplinas?','Não. Acolhem experiências cotidianas e articulam saberes e patrimônios culturais.'],
['Qual concepção de criança orienta o RCP?','Sujeito histórico, social e de direitos, ativo, produtor de cultura e centro do planejamento.'],
['Cuidar e educar podem ser separados?','Não. São indissociáveis.'],
['Qual o papel do PPP?','Consolidar o currículo e as especificidades da instituição, com revisão contínua e participação.'],
['Interação e brincadeira dispensam planejamento?','Não. Exigem intencionalidade, pois objetivos se complexificam conforme idade e percurso.'],
['Qual cuidado na transição EI–EF?','Garantir continuidade, diálogo, acolhimento e direito à infância, evitando rupturas.'],
['A criança deixa de ser criança no Ensino Fundamental?','Não. Ludicidade, corpo, afetos e múltiplas linguagens continuam relevantes.'],
['Onde ocorre alfabetização sistematizada?','No Ensino Fundamental; na EI vivenciam-se funções sociais da leitura e da escrita.'],
['Como ocorre avaliação na EI?','Acompanhamento e registro do processo, sem seleção, promoção ou classificação.'],
['O que deve permear todo o trabalho segundo o RCP?','Inclusão, igualdade, diversidade e equidade.'],
['Qual a relação entre parte comum e contexto local?','Direitos comuns devem dialogar com territórios, culturas, sujeitos e propostas locais.'],
['O RCP vale apenas para a rede estadual?','É referência do Sistema Estadual e para redes/sistemas que o adotam conforme seus atos normativos.'],
['Qual pegadinha central do organizador?','Confundir os três grupos da BNCC com as seis divisões por idade do RCP.'],
['Síntese do Rank 8?','BNCC contextualizada no Paraná: mesmos direitos/eixos/campos, mais detalhamento por idade, objetivos correlacionados e saberes/conhecimentos.']
];
