const R9_FLASHCARDS=[
['O que é Didática?','Campo da Pedagogia que estuda e orienta ensino e aprendizagem, articulando finalidades, conteúdos, métodos, organização e avaliação.'],
['Planejamento e plano são sinônimos?','Não. Planejamento é processo contínuo de reflexão e decisão; plano é seu registro provisório.'],
['Flexibilidade significa improviso?','Não. É capacidade de alterar decisões com critérios e evidências, preservando intencionalidade.'],
['Qual é o ciclo do planejamento?','Diagnóstico, objetivos, experiências, organização, ação, observação, avaliação e replanejamento.'],
['Qual é a função do PPP?','Expressar identidade, diagnóstico, princípios e organização coletiva da instituição.'],
['Qual é a função do PTD?','Concretizar currículo e PPP para um grupo e período, expressando intencionalidades docentes.'],
['O que determina a LDB sobre o plano docente?','O docente deve elaborar e cumprir plano de trabalho segundo a proposta pedagógica da instituição.'],
['O PTD é meramente técnico?','Não. Também expressa escolhas pedagógicas, éticas e políticas.'],
['Quais elementos compõem um PTD?','Diagnóstico, objetivos, experiências/conhecimentos, metodologia, recursos, tempo, inclusão, avaliação e replanejamento.'],
['O que é coerência didática?','Alinhamento entre diagnóstico, objetivos, experiências, mediação e avaliação.'],
['Como formular um objetivo?','Indicar a aprendizagem ou o desenvolvimento que se pretende favorecer na ação da criança.'],
['“Contar uma história” é objetivo suficiente?','Não necessariamente; descreve ação adulta. É melhor explicitar o que a criança poderá ampliar ou realizar.'],
['O interesse infantil é o único critério curricular?','Não. É ponto de partida importante, e o educador amplia o acesso a novos conhecimentos e culturas.'],
['Recurso e metodologia são iguais?','Não. Recurso é meio; metodologia organiza seu uso conforme objetivo, sujeitos, contexto e avaliação.'],
['O que é sequência didática?','Conjunto ordenado e articulado de situações em torno de objetivos e conteúdos, com retomada e progressão.'],
['Sequência didática precisa ser rígida?','Não. A ordem possui justificativa, mas pode mudar a partir das evidências do percurso.'],
['O que caracteriza projeto pedagógico?','Problema, pergunta, necessidade ou produção significativa que mobiliza investigação e etapas conectadas.'],
['O produto final é o centro do projeto?','Não. O processo, a participação, as descobertas e a documentação são centrais.'],
['O que é atividade permanente?','Experiência realizada regularmente porque sustenta aprendizagens contínuas, como leitura diária.'],
['O que é atividade ocasional?','Ação que acolhe acontecimento relevante sem exigir um percurso longo previamente estruturado.'],
['Como deve ser a rotina na Educação Infantil?','Previsível para gerar segurança e flexível para acolher ritmos, necessidades e investigações.'],
['Por que o tempo é decisão curricular?','Sua duração, frequência, esperas e transições podem ampliar ou bloquear exploração e participação.'],
['Por que o espaço educa?','Acessibilidade, disposição e alcance dos materiais comunicam possibilidades de autonomia, encontro e ação.'],
['Como escolher agrupamentos?','Conforme objetivo e necessidades: grande grupo, pequenos grupos, pares ou experiências individuais.'],
['O que é mediação docente?','Organizar condições, observar, escutar, perguntar, ampliar repertórios e graduar apoios.'],
['Mediar é dar a resposta?','Não. A intervenção deve sustentar pensamento e participação sem realizar a ação pela criança.'],
['Participação infantil elimina responsabilidade adulta?','Não. Segurança, direitos e ampliação cultural permanecem responsabilidades profissionais.'],
['O que é planejamento inclusivo?','Antecipar barreiras e oferecer diferentes meios de acesso, participação, comunicação e expressão.'],
['Adaptar significa reduzir objetivos?','Não automaticamente. Pode signific variar caminhos e apoios para garantir direitos comuns.'],
['Qual é a relação entre avaliação e planejamento?','Avaliação produz evidências para manter, modificar, ampliar ou retirar propostas e apoios.'],
['Quando uma sequência é apenas coleção de atividades?','Quando as etapas não se conectam, não retomam aprendizagens nem avançam em complexidade.'],
['Síntese do Rank 9?','Planejar é transformar projeto coletivo em ação coerente, observar seus efeitos e replanejar.']
];
