/* Rank 10 — Gestão democrática, PPP e instâncias colegiadas */
const R10_FLASHCARDS=[
['Qual princípio está no art. 206, VI, da Constituição?','Gestão democrática do ensino público, na forma da lei.'],
['Quem define as normas da gestão democrática segundo a redação atual do art. 14 da LDB?','Lei dos respectivos Estados e Municípios e do Distrito Federal, conforme suas peculiaridades.'],
['Quais são os dois princípios do caput do art. 14 da LDB?','Participação dos profissionais da educação no projeto pedagógico e das comunidades escolar/local em Conselhos e Fóruns ou equivalentes.'],
['O que o art. 15 da LDB assegura?','Progressivos graus de autonomia pedagógica, administrativa e de gestão financeira às unidades públicas.'],
['Autonomia escolar é soberania?','Não. A escola decide dentro da legislação, das políticas públicas e dos direitos.'],
['Participar é apenas estar presente?','Não. Exige condições de compreender, propor, influenciar, decidir quando cabível e acompanhar.'],
['Eleição de diretor esgota a gestão democrática?','Não. Pode ser um mecanismo, mas a democracia depende de processos permanentes e colegiados.'],
['O que significa Projeto no PPP?','Intenção de transformar uma realidade mediante diagnóstico, objetivos e ações.'],
['O que significa Político no PPP?','Escolhas coletivas sobre formação humana, sociedade, direitos e prioridades; não partidarismo.'],
['O que significa Pedagógico no PPP?','Organização das finalidades, currículo, práticas, avaliação e condições educativas.'],
['O PPP é documento ou processo?','É ambos: registro orientador e construção coletiva continuamente executada, avaliada e revisada.'],
['Qual é o ponto de partida do PPP?','Mobilização e diagnóstico participativo da realidade, dos sujeitos, do território e das práticas.'],
['O que transforma objetivo do PPP em ação verificável?','Plano de ação com responsáveis, recursos, prazos e indicadores.'],
['Por que o PPP deve ser flexível?','Porque evidências, necessidades e avaliações institucionais podem exigir revisão fundamentada.'],
['Qual é a natureza do Conselho Escolar na LDB atual?','Órgão deliberativo.'],
['Quem é membro nato do Conselho Escolar?','O diretor da escola.'],
['Como são escolhidos os demais representantes do Conselho?','São eleitos por seus pares nas categorias previstas no art. 14, § 1º.'],
['Quais segmentos compõem o Conselho segundo a LDB?','Profissionais indicados na lei, servidores administrativos, estudantes, pais/responsáveis e comunidade local, além do diretor.'],
['Qual verbo resume a função deliberativa?','Decidir, dentro da competência do colegiado.'],
['Qual verbo resume a função consultiva?','Analisar e opinar.'],
['Qual verbo resume a função fiscalizadora?','Acompanhar e verificar ações, recursos e resultados.'],
['Qual verbo resume a função mobilizadora?','Articular e envolver os segmentos.'],
['Qual é a finalidade do Fórum dos Conselhos Escolares?','Fortalecer os Conselhos e efetivar o processo democrático para melhorar a qualidade da educação.'],
['Quais princípios orientam o Fórum?','Democratização da gestão; do acesso e permanência; e qualidade social da educação.'],
['Qual a composição básica do Fórum na LDB?','Dois representantes do órgão do sistema e dois de cada Conselho Escolar da circunscrição.'],
['Conselho Escolar e APMF são iguais?','Não. O Conselho é órgão colegiado da escola; a APMF é associação privada sem fins lucrativos.'],
['O que significa APMF?','Associação de Pais, Mestres e Funcionários.'],
['Qual a função pedagógica do Conselho de Classe?','Analisar coletivamente ensino e aprendizagem para definir intervenções e replanejar.'],
['Há retenção por avaliação na Educação Infantil?','Não. O acompanhamento e registro não têm objetivo de promoção.'],
['O que o ECA garante aos pais ou responsáveis no art. 53?','Ciência do processo pedagógico e participação na definição das propostas educacionais.'],
['Transparência autoriza expor dados individuais da criança?','Não. Informação pública deve conviver com privacidade e proteção de dados.'],
['Síntese do Rank 10?','Projeto coletivo, participação com influência, colegiados legítimos, autonomia responsável, transparência e avaliação contínua.']
];
