const R10_ADAPTED=[
r10q('r10a1','Adaptada • padrão UniFil','Constituição','Fácil','A Constituição Federal estabelece como princípio do ensino:',['gestão empresarial de toda instituição.','gestão democrática do ensino público, na forma da lei.','autonomia financeira absoluta da escola.','eleição obrigatória de diretores em todas as redes.'],1,'A redação corresponde ao art. 206, VI, da Constituição.','CF art. 206, VI','A literalidade refere-se ao ensino público.'),
r10q('r10a2','Adaptada • lei atual','LDB art. 14','Difícil','Segundo a redação vigente do art. 14 da LDB, as normas da gestão democrática serão definidas:',['por portaria de cada diretor.','exclusivamente por lei federal.','por lei dos respectivos Estados e Municípios e do Distrito Federal.','por assembleia de pais, sem legislação.'],2,'A Lei nº 14.644/2023 alterou o sujeito responsável pela definição normativa.','redação atual do art. 14','Materiais antigos trazem “os sistemas de ensino definirão”.'),
r10q('r10a3','Adaptada • padrão UniFil','PPP','Médio','Na gestão democrática, o Projeto Político-Pedagógico deve ser:',['construído coletivamente, executado, avaliado e revisado.','redigido exclusivamente pela direção e arquivado.','imutável durante toda a existência da instituição.','substituído por planos individuais dos docentes.'],0,'O PPP é documento-processo coletivo e flexível, não peça burocrática.','natureza do PPP','Coletivo não significa ausência de coordenação.'),
r10q('r10a4','Adaptada • literalidade','LDB art. 15','Médio','A LDB assegura às unidades escolares públicas:',['soberania curricular.','independência em relação ao sistema.','autonomia apenas disciplinar.','progressivos graus de autonomia pedagógica, administrativa e de gestão financeira.'],3,'Essa é a estrutura literal do art. 15, observadas as normas de direito financeiro público.','autonomia escolar','A palavra decisiva é “progressivos”.'),
r10q('r10a5','Adaptada • padrão UniFil','Participação','Fácil','A participação democrática pressupõe:',['apenas presença em eventos.','acesso à informação e possibilidade real de influir nas decisões.','confirmação de decisões já tomadas.','transferência de toda responsabilidade às famílias.'],1,'Participação efetiva vai além da presença formal e produz influência e acompanhamento.','participação efetiva','Informar é necessário, mas nem sempre suficiente.'),
r10q('r10a6','Adaptada • literalidade','Conselho Escolar','Médio','Na LDB atual, o Conselho Escolar é definido como órgão:',['exclusivamente consultivo.','executivo privado.','deliberativo.','jurisdicional.'],2,'O art. 14, § 1º, qualifica expressamente o Conselho Escolar como deliberativo.','natureza do Conselho Escolar','Outras funções aparecem em materiais e normas locais.'),
r10q('r10a7','Adaptada • composição','Conselho Escolar','Fácil','No Conselho Escolar, o diretor é:',['membro nato.','representante eleito dos pais.','observador sem voz.','indicado pelo grêmio.'],0,'A LDB estabelece que o Diretor da Escola é membro nato.','composição do Conselho','Os demais representantes são eleitos por seus pares.'),
r10q('r10a8','Adaptada • conceito','Funções','Médio','A função que corresponde a acompanhar a aplicação de recursos e a execução de ações é a:',['mobilizadora.','consultiva.','pedagógica.','fiscalizadora.'],3,'Fiscalizar é verificar processos, aplicação de recursos e cumprimento de decisões.','funções do Conselho','Fiscalização não equivale a perseguição.'),
r10q('r10a9','Adaptada • lei atual','Fórum','Difícil','O Fórum dos Conselhos Escolares tem como finalidade central:',['substituir todos os Conselhos de escola.','fortalecer os Conselhos da circunscrição e efetivar o processo democrático.','administrar diretamente cada unidade.','selecionar estudantes para vagas.'],1,'O Fórum articula e fortalece Conselhos sem assumir o lugar de cada unidade.','Fórum dos Conselhos','Fórum e Conselho atuam em escalas distintas.'),
r10q('r10a10','Adaptada • conceito','PPP','Fácil','O termo “político” no PPP refere-se:',['às escolhas coletivas de formação, sociedade e direitos.','à propaganda partidária obrigatória.','à eleição da direção apenas.','ao registro financeiro anual.'],0,'Toda proposta educacional expressa finalidades sociais e escolhas de formação humana.','dimensão política do PPP','Político não é sinônimo de partidário.'),
r10q('r10a11','Adaptada • diferenciação','Instâncias','Médio','Assinale a alternativa correta.',['Conselho Escolar e APMF são a mesma pessoa jurídica.','A APMF substitui a responsabilidade do poder público.','O Conselho é órgão colegiado; a APMF é associação privada sem fins lucrativos.','A APMF possui competência legislativa.'],2,'As entidades podem cooperar, mas têm natureza e atribuições diferentes.','Conselho × APMF','Proximidade na prática não apaga a distinção jurídica.'),
r10q('r10a12','Adaptada • ECA','Família','Médio','Segundo o ECA, é direito dos pais ou responsáveis:',['definir individualmente todo o currículo.','dispensar a criança da proposta comum.','substituir a avaliação institucional.','ter ciência do processo pedagógico e participar da definição das propostas educacionais.'],3,'A formulação está no parágrafo único do art. 53 do ECA.','participação familiar','Participar não significa decidir sozinho.'),
r10q('r10a13','Adaptada • situação','Conselho de Classe','Médio','O Conselho de Classe cumpre função pedagógica quando:',['apenas soma notas.','analisa coletivamente condições de ensino e define intervenções.','classifica famílias.','decide punições sem escuta.'],1,'O colegiado deve produzir compreensão e replanejamento, não culpabilização.','Conselho de Classe','Na Educação Infantil não há avaliação para promoção.'),
r10q('r10a14','Adaptada • conceito','Transparência','Fácil','Transparência na gestão escolar significa:',['dar acesso a informações, critérios, decisões e prestação de contas.','publicar diagnósticos individuais de crianças.','eliminar qualquer confidencialidade.','comunicar apenas resultados positivos.'],0,'A informação acessível viabiliza participação e controle social, preservando dados pessoais.','transparência e privacidade','Publicidade institucional não autoriza exposição individual.'),
r10q('r10a15','Adaptada • síntese','Gestão democrática','Difícil','É compatível com gestão democrática:',['maioria decidir contra direito fundamental.','direção transferir toda obrigação ao colegiado.','debate plural, decisão competente, registro, execução e avaliação.','consulta realizada somente após a execução.'],2,'Democracia articula participação, competência, legalidade e acompanhamento.','síntese da gestão democrática','Votação não legitima ilegalidade.')
];
const R10_AUTHORIAL=[
r10q('r10b1','Autoral • situação prática','Participação','Médio','A direção apresenta uma decisão pronta e pede assinaturas ao final da reunião. Para democratizar o processo, deveria:',['manter a decisão e ampliar a lista de presença.','apresentar previamente problema e dados, acolher propostas e deliberar antes da decisão.','cancelar toda coordenação.','transferir a decisão a uma única família.'],1,'Participação autêntica ocorre antes da decisão e admite influência real.','qualidade da participação','Assinatura comprova presença, não poder decisório.'),
r10q('r10b2','Autoral • situação prática','PPP','Médio','Um PPP elaborado por consultoria externa foi copiado e arquivado. A principal falha é:',['ter formatação profissional.','conter referências teóricas.','não expressar diagnóstico, identidade e autoria coletiva da instituição.','ser um documento escrito.'],2,'A forma não compensa a ausência de construção coletiva e vínculo com a realidade.','autoria do PPP','Apoio externo pode colaborar, mas não substituir a comunidade.'),
r10q('r10b3','Autoral • autonomia','Autonomia','Difícil','O Conselho propõe retirar um direito curricular para reduzir custos. A direção deve:',['executar porque houve maioria.','submeter a sorteio.','ocultar a decisão da comunidade.','impedir a violação, explicar os limites legais e buscar alternativa legítima.'],3,'Autonomia e deliberação são limitadas pela legislação e pelos direitos educacionais.','limites da autonomia','Maioria não torna lícita a decisão.'),
r10q('r10b4','Autoral • gestão','Liderança','Médio','Liderança democrática caracteriza-se por:',['coordenar processos, distribuir informações e sustentar decisões coletivas legítimas.','abandonar toda decisão à espontaneidade.','evitar conflitos por meio do silêncio.','consultar apenas quem concorda.'],0,'Liderança e democracia são compatíveis quando há coordenação, diálogo e responsabilidade.','liderança democrática','Gestão compartilhada não é ausência de gestão.'),
r10q('r10b5','Autoral • representação','Representatividade','Médio','Um conselheiro decide sempre conforme opinião pessoal, sem conversar com seu segmento. Isso fragiliza:',['a infraestrutura.','a representatividade e a prestação de contas.','a matrícula.','o calendário.'],1,'Representar implica escutar pares, atuar no colegiado e comunicar decisões.','representação colegiada','Eleição, sozinha, não garante representação contínua.'),
r10q('r10b6','Autoral • funções','Função consultiva','Médio','O Conselho estuda três alternativas e emite parecer para a instância competente decidir. Exerce função:',['deliberativa.','fiscalizadora.','consultiva.','executiva.'],2,'Analisar e opinar, sem produzir a decisão final, caracteriza consulta.','função consultiva','Não confunda parecer com deliberação.'),
r10q('r10b7','Autoral • Fórum','Fórum','Difícil','Vários Conselhos de uma rede identificam problema comum e precisam articular formação e propostas ao sistema. A instância mais adequada é:',['a APMF de uma escola.','um Conselho de Classe.','o grêmio de uma turma.','o Fórum dos Conselhos Escolares.'],3,'O Fórum atua na articulação e no fortalecimento dos Conselhos de sua circunscrição.','competência do Fórum','A escala do problema indica a instância.'),
r10q('r10b8','Autoral • Educação Infantil','Participação infantil','Médio','Crianças pequenas demonstram, por falas e gestos, que um espaço não as acolhe. Uma resposta democrática é:',['documentar a escuta, testar mudanças seguras e devolver ao grupo o que foi feito.','ignorar porque não votam formalmente.','permitir qualquer mudança sem responsabilidade adulta.','pedir apenas aos pais que escolham.'],0,'Participação infantil usa múltiplas linguagens e preserva deveres profissionais.','participação das crianças','Escuta não é obediência automática.'),
r10q('r10b9','Autoral • dados','Proteção de dados','Difícil','Em nome da transparência, alguém propõe publicar nomes e dificuldades de crianças. A conduta correta é:',['publicar tudo em rede social.','divulgar indicadores institucionais protegidos e restringir dados individuais.','ocultar toda informação da escola.','entregar os dados a qualquer interessado.'],1,'Transparência deve coexistir com privacidade, finalidade e proteção integral.','transparência e dados pessoais','Dados agregados permitem análise sem exposição.'),
r10q('r10b10','Autoral • avaliação','Avaliação institucional','Médio','Após avaliar o PPP, a comunidade constata que uma meta não avançou. O passo mais adequado é:',['apagar o diagnóstico.','manter a ação para evitar reconhecer erro.','analisar causas e evidências, redefinindo ação, responsáveis ou condições.','culpar um segmento sem apuração.'],2,'Avaliação institucional serve para reorientar decisões e condições.','revisão do PPP','Flexibilidade requer fundamento.'),
r10q('r10b11','Autoral • instâncias','APMF','Médio','Uma APMF habilitada recebe recursos e presta contas. Disso se conclui que ela:',['se tornou poder legislativo.','substituiu a mantenedora.','passou a ser idêntica ao Conselho.','atua conforme estatuto e regras financeiras, sem absorver todas as competências escolares.'],3,'A atuação financeira não elimina a natureza associativa nem transfere competências institucionais.','APMF e Unidade Executora','Executar recursos não significa governar sozinha.'),
r10q('r10b12','Autoral • conflito','Conflitos','Médio','Em reunião há discordância intensa, mas respeitosa. A atitude mais democrática é:',['delimitar o problema, garantir fala, analisar direitos e deliberar conforme regras.','encerrar o debate e decidir secretamente.','exigir unanimidade artificial.','excluir a posição minoritária da ata.'],0,'Conflito de ideias pode qualificar a decisão quando há regras, informação e respeito.','mediação de conflitos','Democracia não exige ausência de divergência.'),
r10q('r10b13','Autoral • planejamento','PPP em ação','Difícil','A melhor evidência de que o PPP está vivo é:',['sua capa atualizada.','sua presença nos planos, decisões, recursos, avaliações e revisões da escola.','o número de páginas.','a assinatura de uma única autoridade.'],1,'Um projeto vivo orienta a ação e é reavaliado com base em evidências.','execução do PPP','Documento bonito não prova uso.'),
r10q('r10b14','Autoral • Conselho de Classe','Avaliação na EI','Médio','Na Educação Infantil, um Conselho de Classe propõe reter criança por não atingir metas. A proposta é:',['adequada se a família concordar.','válida por maioria simples.','incompatível com avaliação sem objetivo de promoção, devendo-se planejar apoios e continuidade.','obrigatória antes do Ensino Fundamental.'],2,'Na Educação Infantil, acompanhamento e registro não têm finalidade de promoção/retenção.','avaliação na Educação Infantil','Colegiado não pode criar retenção proibida.'),
r10q('r10b15','Autoral • síntese','Ciclo democrático','Difícil','Qual sequência melhor representa gestão democrática eficaz?',['comunicar → assinar → arquivar.','votar → expor → punir.','delegar → esquecer → improvisar.','diagnosticar → informar → participar → deliberar → executar → avaliar.'],3,'A sequência integra conhecimento da realidade, participação, ação e revisão.','ciclo democrático','A deliberação precisa gerar execução e acompanhamento.')
];
